# Scoring-Engine der Flächenakquise – Python-Gegenstück zu src/lib/plattform/geodaten/scoring.js.
# Reine Funktionen ohne GIS-Bibliotheken (lokal mit `python -m unittest` testbar). Identische Regeln, Schwellen
# und Konstanten wie die JS-Fassung; tests/faelle.json enthält gemeinsame Testfälle mit den Ergebnissen der JS-Engine.
#
# Kriterien (Höchstpunkte): Größe 20 · Form 8 · Neigung/Exposition 12 · Nutzung 8 · Siedlungsabstand 8 ·
# Netz (Trassenlänge) 22 · Netzanschlusskosten 8 · Widmungslage 10 · Einstrahlung 4 = 100.
# Abzüge: Schutzgebiete, knappe Netzkapazität. K.-o.-Kriterien deckeln den Punktwert.

from .geometrie import distanz_m
from .netz import FREIFLAECHE, PACHT, ebene_fuer, jsround, netzkosten

SCORING_VERSION = "2026-09-30.1"

GEWICHTE = {"groesse": 20, "form": 8, "neigung": 12, "nutzung": 8, "siedlung": 8, "netz": 22, "kosten": 8, "widmung": 10, "einstrahlung": 4}
TRASSE = {"umwegFaktor": 1.25, "querungZuschlagM": 150, "suchradiusKm": 25}
SCHWELLEN = {"mindestHa": 2, "idealHa": (5, 50), "maxNeigungGrad": 15, "siedlungAbstandM": (100, 300), "ampel": {"gruen": 65, "gelb": 45}}

SCHUTZ_ARTEN = {
	"nationalpark": {"label": "Nationalpark", "kern": True, "abzugNah": 6},
	"natura2000": {"label": "Natura 2000 / Europaschutzgebiet", "kern": True, "abzugNah": 6},
	"naturschutz": {"label": "Naturschutzgebiet", "kern": True, "abzugNah": 5},
	"wasserschutz": {"label": "Wasserschutz-/Schongebiet", "kern": False, "abzug": 10, "abzugNah": 0},
	"landschaftsschutz": {"label": "Landschaftsschutzgebiet", "kern": False, "abzug": 8, "abzugNah": 2},
	"sonstig": {"label": "sonstiges Schutzgebiet", "kern": False, "abzug": 5, "abzugNah": 0},
}

KNOTEN_ARTEN = {
	"uew": "UW 380/220 kV",
	"uw110": "UW 110 kV",
	"ms": "UW MS",
	"trafo": "Trafostation",
}
KNOTEN_FUER_EBENE = {"msLeitung": ("trafo", "ms", "uw110"), "uwMs": ("uw110",), "hs": ("uw110", "uew")}

ERTRAG = {
	"Burgenland": 1210, "Kärnten": 1240, "Niederösterreich": 1190, "Oberösterreich": 1130, "Salzburg": 1140, "Steiermark": 1220,
	"Tirol": 1370, "Vorarlberg": 1130, "Wien": 1190, "_AT": 1120, "_DE": 1020, "_CH": 1050,
}

WIDMUNG = {
	"Oberösterreich": {"art": "uw_radius", "zoneKm": 5, "angrenzendKm": 7.5, "text": "Kriterienkatalog PV-FFA: energiewirtschaftliche Priorität 1 (≤ 5 km zum Umspannwerk) bzw. 2 (≤ 7,5 km); Bodenfruchtbarkeit Stufe 4–5 im Einzelfall prüfen (DORIS)."},
	"Niederösterreich": {"art": "zonen", "angrenzendM": 200, "maxHaAusserhalb": 2, "text": "SekRop PV: 116 Zonen (je Zone 5 ha, mit Ökologiekonzept 10 ha); außerhalb höchstens 2 ha, Zusammenrechnung im 200-m-Umkreis."},
	"Burgenland": {"art": "zonen", "angrenzendM": 0, "maxHaAusserhalb": 0, "text": "Freiflächen-PV nur in Eignungszonen (Bgld. RPG 2019 § 22d); unter 10 ha zusätzlich Widmung nötig."},
	"Steiermark": {"art": "zonen", "angrenzendM": 500, "text": "SAPRO Solarenergie: 36 Vorrangzonen (> 10 ha); außerhalb Sondernutzung im Freiland über die Gemeinde, Ausschlusszonen beachten."},
	"Salzburg": {"art": "einzelfall", "text": "Kennzeichnung nach § 39b ROG 2009 über 200 m² mit Punktesystem der PV-Kennzeichnungsverordnung 2023 (je Bodenkategorie 20–40 Punkte)."},
	"Kärnten": {"art": "einzelfall", "maxHa": 4, "text": "Widmung „Grünland – Photovoltaikanlage“, zusammenhängend max. 4 ha, 1.000 m Abstand zwischen Widmungsflächen (K-PhV 2024)."},
	"Tirol": {"art": "einzelfall", "text": "Sonderfläche bis 250 kWp, darüber Bewilligung nach TEG – Einzelfall."},
	"Vorarlberg": {"art": "einzelfall", "text": "Sondergebiet in der Freifläche; Landesgrünzone Rheintal/Walgau beachten."},
	"Wien": {"art": "einzelfall", "text": "Vorbelastete Flächen bevorzugt; Grünland-Schutzgebiet beachten."},
}

SUED = ("S", "SO", "SW", "eben")


def r1(x):
	return jsround(x * 10) / 10


def clamp(x, a=0.0, b=1.0):
	return max(a, min(b, x))


def mwp_fuer(ha):
	return r1((float(ha or 0)) / FREIFLAECHE["haProMwp"])


def trasse_m(luftlinie_m, querungen=0):
	return jsround(luftlinie_m * TRASSE["umwegFaktor"] + max(0, querungen) * TRASSE["querungZuschlagM"])


def bester_knoten(punkt, mwp, knoten, querungen=None):
	"""Bester Netzknoten nach geschätzten Anschlusskosten im Suchradius (wie besterKnoten in scoring.js).
	punkt = (lon, lat); knoten = [{id, name, art, spannungKv, kapazitaet, lon, lat}]; querungen(k) -> int."""
	ebene = ebene_fuer(mwp)
	arten = KNOTEN_FUER_EBENE[ebene]
	best = None
	for k in knoten:
		if k.get("art") not in arten:
			continue
		luft = distanz_m(punkt, (k["lon"], k["lat"]))
		if luft > TRASSE["suchradiusKm"] * 1000:
			continue
		tr = trasse_m(luft, querungen(k) if querungen else 0)
		kosten = netzkosten(mwp, tr / 1000, "msLeitung" if k["art"] in ("trafo", "ms") else ebene, k.get("kapazitaet") or "unbekannt")
		wert = kosten["summe"] * (1.5 if k.get("kapazitaet") == "knapp" else 1)
		if best is None or wert < best["_wert"] or (wert == best["_wert"] and luft < best["luftlinieM"]):
			best = {"knoten": k, "luftlinieM": jsround(luft), "trasseM": tr, "kosten": kosten, "ebene": kosten["ebene"], "_wert": wert}
	if best:
		best.pop("_wert")
	return best


def naechster_knoten(punkt, knoten, arten=("uw110", "uew")):
	best = None
	for k in knoten:
		if k.get("art") not in arten:
			continue
		d = distanz_m(punkt, (k["lon"], k["lat"]))
		if best is None or d < best["luftlinieM"]:
			best = {"knoten": k, "luftlinieM": jsround(d)}
	return best


def _km(x):
	return str(x).replace(".", ",")


def widmungslage(bundesland=None, uw_abstand_km=None, zone_abstand_m=None):
	regel = WIDMUNG.get(bundesland)
	if not regel:
		return {"status": "unklar", "text": "Keine Widmungsregel hinterlegt – Einzelfallprüfung.", "regel": None}
	if regel["art"] == "uw_radius":
		if uw_abstand_km is None:
			return {"status": "unklar", "text": regel["text"], "regel": regel}
		if uw_abstand_km <= regel["zoneKm"]:
			return {"status": "zone", "text": f"Priorität 1 (≤ {regel['zoneKm']} km zum Umspannwerk). {regel['text']}", "regel": regel}
		if uw_abstand_km <= regel["angrenzendKm"]:
			return {"status": "angrenzend", "text": f"Priorität 2 (≤ {_km(regel['angrenzendKm'])} km zum Umspannwerk). {regel['text']}", "regel": regel}
		return {"status": "ausserhalb", "text": f"Außerhalb der Prioritätsradien. {regel['text']}", "regel": regel}
	if regel["art"] == "zonen":
		if zone_abstand_m is None:
			return {"status": "unklar", "text": f"Zonendaten nicht geladen. {regel['text']}", "regel": regel}
		if zone_abstand_m <= 0:
			return {"status": "zone", "text": f"Innerhalb einer verordneten Zone. {regel['text']}", "regel": regel}
		if regel.get("angrenzendM") and zone_abstand_m <= regel["angrenzendM"]:
			return {"status": "angrenzend", "text": f"Angrenzend an eine Zone ({jsround(zone_abstand_m)} m). {regel['text']}", "regel": regel}
		return {"status": "ausserhalb", "text": f"Außerhalb der Zonen. {regel['text']}", "regel": regel}
	return {"status": "unklar", "text": regel["text"], "regel": regel}


def bewerte(m):
	"""Punktwert einer Kandidatenfläche – Eingabe/Ausgabe wie bewerte() in scoring.js (Texte ohne Zahlformatierung)."""
	k = []
	ko = []

	def add(id_, label, punkte, maximum, text, art=None):
		if art is None:
			art = "plus" if punkte >= maximum * 0.66 else ("neutral" if punkte > 0 else "minus")
		k.append({"id": id_, "label": label, "punkte": r1(punkte), "max": maximum, "text": text, "art": art})

	ha = float(m.get("ha") or 0)
	mwp = mwp_fuer(ha)

	# Größe
	if ha < SCHWELLEN["mindestHa"]:
		pg = 0
		ko.append({"id": "groesse", "text": f"Unter {SCHWELLEN['mindestHa']} ha – für Freiflächen-PV meist unwirtschaftlich.", "deckel": 25})
	elif ha < 3:
		pg = 6
	elif ha < SCHWELLEN["idealHa"][0]:
		pg = 6 + ((ha - 3) / 2) * 8
	elif ha <= SCHWELLEN["idealHa"][1]:
		pg = 20
	else:
		pg = 16
	add("groesse", "Größe", pg, GEWICHTE["groesse"], f"{r1(ha)} ha")

	# Form
	kp = clamp(float(m.get("kompaktheit") or 0))
	add("form", "Form/Kompaktheit", clamp((kp - 0.45) / 0.45) * GEWICHTE["form"], GEWICHTE["form"], "kompakt" if kp >= 0.85 else ("brauchbar" if kp >= 0.65 else "zerklüftet/schmal"))

	# Neigung/Exposition
	n = max(0.0, float(m.get("neigungGrad") or 0))
	exp = m.get("exposition") or "eben"
	sued = exp in SUED or n <= 2
	if n <= 3:
		pn = 12
	elif n <= 7:
		pn = 10 if sued else 6
	elif n <= 12:
		pn = 6 if sued else 1
	else:
		pn = 2 if sued else 0
	if n > SCHWELLEN["maxNeigungGrad"]:
		ko.append({"id": "neigung", "text": f"Mittlere Neigung {r1(n)}° – zu steil.", "deckel": 20})
	add("neigung", "Neigung/Exposition", pn, GEWICHTE["neigung"], f"{r1(n)}°, {exp}")

	# Nutzung
	nu = m.get("nutzung") or {}
	acker, gruen, sonst = float(nu.get("acker") or 0), float(nu.get("gruenland") or 0), float(nu.get("sonstige") or 0)
	summe = (acker + gruen + sonst) or 1
	add("nutzung", "Nutzung", (acker * 8 + gruen * 7 + sonst * 3) / summe, GEWICHTE["nutzung"], "Acker" if acker >= gruen else "Grünland")

	# Schutzgebiete
	for s in m.get("schutz") or []:
		d = SCHUTZ_ARTEN.get(s.get("art")) or SCHUTZ_ARTEN["sonstig"]
		anteil = clamp(float(s.get("anteil") or 0))
		abstand = s.get("abstandM")
		abstand = float("inf") if abstand is None else float(abstand)
		if anteil > 0.05 and d["kern"]:
			ko.append({"id": f"schutz_{s.get('art')}", "text": f"{jsround(anteil * 100)} % im {d['label']} – in der Regel ausgeschlossen.", "deckel": 15})
			add(f"schutz_{s.get('art')}", d["label"], -10, 0, f"überdeckt {jsround(anteil * 100)} %", "ko")
		elif anteil > 0.05:
			add(f"schutz_{s.get('art')}", d["label"], -d["abzug"] * min(1, anteil * 2), 0, f"überdeckt {jsround(anteil * 100)} %", "minus")
		elif abstand <= 200 and d.get("abzugNah"):
			add(f"schutz_{s.get('art')}", f"Nähe {d['label']}", -d["abzugNah"], 0, f"{jsround(abstand)} m entfernt", "minus")

	# Siedlungsabstand
	sa = m.get("siedlungAbstandM")
	s_min, s_voll = SCHWELLEN["siedlungAbstandM"]
	if sa is None:
		ps = 4
	else:
		sa = float(sa)
		ps = 0 if sa < s_min else (8 if sa >= s_voll else 4 + ((sa - s_min) / (s_voll - s_min)) * 4)
	add("siedlung", "Abstand Siedlung", ps, GEWICHTE["siedlung"], "unbekannt" if sa is None else f"{jsround(sa)} m")

	# Netz
	netz = m.get("netz")
	if netz:
		km = netz["trasseM"] / 1000
		if km <= 1:
			p = 22
		elif km <= 3:
			p = 22 - ((km - 1) / 2) * 4
		elif km <= 5:
			p = 18 - ((km - 3) / 2) * 5
		elif km <= 8:
			p = 13 - ((km - 5) / 3) * 6
		elif km <= 12:
			p = 7 - ((km - 8) / 4) * 4
		else:
			p = max(0, 3 - (km - 12) / 4)
		kn = netz.get("knoten") or {}
		add("netz", "Netzanschluss (Trasse)", p, GEWICHTE["netz"], f"{r1(km)} km Trasse")
		if kn.get("kapazitaet") == "knapp":
			add("kapazitaet", "Netzkapazität", -8, 0, "knapp", "minus")
		elif kn.get("kapazitaet") == "frei":
			add("kapazitaet", "Netzkapazität", 3, 0, "frei", "plus")
		anteil = (netz.get("kosten") or {}).get("anteil", 1)
		if anteil < 0.08:
			pk = 8
		elif anteil < 0.15:
			pk = 8 - ((anteil - 0.08) / 0.07) * 3
		elif anteil < 0.25:
			pk = 5 - ((anteil - 0.15) / 0.1) * 3
		else:
			pk = max(0, 2 - (anteil - 0.25) * 10)
		add("kosten", "Netzanschlusskosten", pk, GEWICHTE["kosten"], f"{jsround(anteil * 100)} % der Anlagenkosten")
	else:
		add("netz", "Netzanschluss (Trasse)", 0, GEWICHTE["netz"], "kein Netzknoten im Suchradius", "minus")
		add("kosten", "Netzanschlusskosten", 0, GEWICHTE["kosten"], "nicht bestimmbar", "minus")

	# Widmung
	w = m.get("widmung") or {"status": "unklar"}
	pw = {"zone": 10, "angrenzend": 6, "unklar": 4, "ausserhalb": 2}.get(w.get("status"), 4)
	add("widmung", "Widmungslage", pw, GEWICHTE["widmung"], w.get("status") or "unklar")
	regel = w.get("regel") or WIDMUNG.get(m.get("bundesland"))
	if regel and "maxHaAusserhalb" in regel and w.get("status") != "zone" and ha > regel["maxHaAusserhalb"]:
		ko.append({"id": "widmung", "text": "Außerhalb der Zonen nur eingeschränkt widmungsfähig.", "deckel": 45 if regel["maxHaAusserhalb"] > 0 else 20})
	if regel and regel.get("maxHa") and ha > regel["maxHa"]:
		add("widmung_max", "Widmungsgrenze", -3, 0, f"max. {regel['maxHa']} ha je Widmung", "minus")

	# Einstrahlung
	ertrag = ERTRAG.get(m.get("bundesland")) or ERTRAG.get(f"_{m.get('land') or 'AT'}") or ERTRAG["_AT"]
	add("einstrahlung", "Einstrahlung", clamp((ertrag - 1000) / 200) * GEWICHTE["einstrahlung"], GEWICHTE["einstrahlung"], f"{ertrag} kWh/kWp")

	score = sum(x["punkte"] for x in k)
	score = max(0, min(100, score))
	for x in ko:
		score = min(score, x["deckel"])
	score = jsround(score)
	ampel = "gruen" if score >= SCHWELLEN["ampel"]["gruen"] else ("gelb" if score >= SCHWELLEN["ampel"]["gelb"] else "rot")
	return {"score": score, "ampel": ampel, "ko": ko, "kriterien": k, "mwp": mwp, "ertragKwhProKwp": ertrag}


def kennzahlen(ha, ertrag_kwh_pro_kwp=ERTRAG["_AT"], agri=False):
	mwp = mwp_fuer(ha)
	p = PACHT["agriProHa"] if agri else PACHT["freiflaecheProHa"]
	return {
		"mwp": mwp,
		"ertragMwh": jsround(mwp * ertrag_kwh_pro_kwp),
		"pachtJahr": {"min": jsround(ha * p["min"]), "mittel": jsround(ha * p["mittel"]), "max": jsround(ha * p["max"])},
		"capex": {"min": jsround(mwp * 1000 * FREIFLAECHE["capexProKwp"]["min"]), "max": jsround(mwp * 1000 * FREIFLAECHE["capexProKwp"]["max"])},
	}


def prioritaet(score, ha):
	if score >= 65 and float(ha or 0) >= 5:
		return "A"
	if score >= 45:
		return "B"
	return "C"
# Tests der reinen Scoring-Logik (ohne GIS-Bibliotheken, ohne Datenbank):
#   cd Backend-Import/dienste/geodaten && python -m unittest discover -s tests -v
# tests/faelle.json enthält Ergebnisse der JS-Engine (src/lib/plattform/geodaten/scoring.js) – beide Seiten müssen
# übereinstimmen. Neu erzeugen: node Backend-Import/dienste/geodaten/tests/faelle_erzeugen.mjs (Website-Repository).

import json
import os
import unittest

from geodaten import scoring as s
from geodaten.geometrie import distanz_m, flaeche_m2, kompaktheit, neigung_exposition, punkt_in_polygon
from geodaten.netz import jsround, netzkosten

HIER = os.path.dirname(os.path.abspath(__file__))
with open(os.path.join(HIER, "faelle.json"), encoding="utf-8") as f:
	FAELLE = json.load(f)


class GleichMitJs(unittest.TestCase):
	def test_version(self):
		self.assertEqual(FAELLE["version"], s.SCORING_VERSION, "Scoring-Version JS/Python unterschiedlich – faelle.json neu erzeugen")

	def test_bewertung(self):
		for fall in FAELLE["bewertung"]:
			with self.subTest(fall["name"]):
				r = s.bewerte(fall["eingabe"])
				e = fall["erwartet"]
				self.assertEqual(r["score"], e["score"])
				self.assertEqual(r["ampel"], e["ampel"])
				self.assertEqual([k["id"] for k in r["ko"]], e["ko"])
				self.assertEqual({k["id"]: k["punkte"] for k in r["kriterien"]}, e["punkte"])
				self.assertEqual(r["mwp"], e["mwp"])

	def test_netzkosten(self):
		for fall in FAELLE["netzkosten"]:
			with self.subTest(f"{fall['mwp']} MWp {fall['km']} km"):
				self.assertEqual(netzkosten(fall["mwp"], fall["km"], fall["ebene"], fall["kapazitaet"]), fall["erwartet"])

	def test_bester_knoten(self):
		for fall in FAELLE["bester"]:
			with self.subTest(str(fall["punkt"])):
				b = s.bester_knoten(tuple(fall["punkt"]), fall["mwp"], FAELLE["knoten"])
				e = fall["erwartet"]
				if e is None:
					self.assertIsNone(b)
					continue
				self.assertEqual(b["knoten"]["id"], e["id"])
				self.assertEqual(b["luftlinieM"], e["luftlinieM"])
				self.assertEqual(b["trasseM"], e["trasseM"])
				self.assertEqual(b["kosten"]["summe"], e["summe"])

	def test_distanz(self):
		for fall in FAELLE["distanz"]:
			self.assertAlmostEqual(distanz_m(fall["a"], fall["b"]), fall["erwartetM"], places=2)

	def test_kompaktheit(self):
		for fall in FAELLE["kompaktheit"]:
			self.assertAlmostEqual(flaeche_m2(fall["geo"]), fall["flaecheM2"], delta=0.1)
			self.assertEqual(kompaktheit([fall["geo"]], flaeche_m2(fall["geo"])), fall["erwartet"])


class Regeln(unittest.TestCase):
	BASIS = {"ha": 12, "kompaktheit": 0.95, "neigungGrad": 2, "exposition": "S", "nutzung": {"acker": 12}, "schutz": [], "siedlungAbstandM": 500, "bundesland": "Oberösterreich", "land": "AT", "widmung": {"status": "zone"}}

	def netz(self, km, kap="unbekannt"):
		return {"knoten": {"art": "trafo", "kapazitaet": kap}, "luftlinieM": km * 800, "trasseM": km * 1000, "kosten": netzkosten(10.9, km, "msLeitung", kap)}

	def test_distanz_bekannt(self):
		# Braunau am Inn → Ried im Innkreis ≈ 34 km Luftlinie
		self.assertAlmostEqual(distanz_m((13.0346, 48.2566), (13.4886, 48.2107)) / 1000, 34.0, delta=0.6)
		self.assertAlmostEqual(distanz_m((0, 0), (0, 1)), 111195, delta=5)

	def test_trasse(self):
		self.assertEqual(s.trasse_m(1000), 1250)
		self.assertEqual(s.trasse_m(1000, 2), 1550)

	def test_trasse_monoton(self):
		werte = [s.bewerte({**self.BASIS, "netz": self.netz(km)})["score"] for km in (0.5, 2, 4, 7, 11, 20)]
		self.assertEqual(werte, sorted(werte, reverse=True))

// src/lib/plattform/geodaten/scoring.js
//
// Scoring-Engine der Flächenakquise (reine Funktionen, Client + Server). Bewertet eine Kandidatenfläche –
// eine Parzelle oder einen zusammenhängenden Verbund mehrerer Parzellen/Schläge – mit 0–100 Punkten und
// Begründung. Gegenstück in Python (identische Regeln und Konstanten, gemeinsame Testfälle):
//   Backend-Import/dienste/geodaten/geodaten/scoring.py  ·  tests/faelle.json
//
// Kriterien (Höchstpunkte): Größe 20 · Form 8 · Neigung/Exposition 12 · Nutzung 8 · Siedlungsabstand 8 ·
// Netz (Trassenlänge) 22 · Netzanschlusskosten 8 · Widmungslage 10 · Einstrahlung 4 = 100.
// Abzüge: Schutzgebiete (Nähe/Überdeckung), knappe Netzkapazität. K.-o.-Kriterien deckeln den Punktwert
// (zu klein, Kern-Schutzgebiet, zu steil).
//
// Netzanschlusskosten: Logik des Netzanschluss-Rechners (src/lib/rechner/netzanschluss.js, FREIFLAECHE.netz).
// Alle Werte sind Schätzungen für die Vorauswahl – maßgeblich sind Netzbetreiber-Auskunft und Standortprüfung.

import { FREIFLAECHE, PACHT } from "../../invest/markt.js";
import { rechneNetzanschluss, ebeneFuer } from "../../rechner/netzanschluss.js";
import { distanzM } from "./geo.js";

export const SCORING_VERSION = "2026-09-30.1";

export const GEWICHTE = { groesse: 20, form: 8, neigung: 12, nutzung: 8, siedlung: 8, netz: 22, kosten: 8, widmung: 10, einstrahlung: 4 };

/** Näherung Trassenlänge: Luftlinie × Umwegfaktor + Zuschlag je Querung (Straße ab Landesstraße, Bahn, Fluss) */
export const TRASSE = { umwegFaktor: 1.25, querungZuschlagM: 150, suchradiusKm: 25 };

/** Schwellen der Bewertung */
export const SCHWELLEN = {
  mindestHa: 2, // darunter K.-o. (Deckel)
  idealHa: [5, 50],
  maxNeigungGrad: 15, // darüber K.-o. (Deckel)
  siedlungAbstandM: [100, 300], // < 100 m kritisch, ≥ 300 m voll
  ampel: { gruen: 65, gelb: 45 },
};

/** Schutzgebietsarten: kern = Ausschluss (Deckel), sonst Abzug */
export const SCHUTZ_ARTEN = {
  nationalpark: { label: "Nationalpark", kern: true, abzugNah: 6 },
  natura2000: { label: "Natura 2000 / Europaschutzgebiet", kern: true, abzugNah: 6 },
  naturschutz: { label: "Naturschutzgebiet", kern: true, abzugNah: 5 },
  wasserschutz: { label: "Wasserschutz-/Schongebiet", kern: false, abzug: 10, abzugNah: 0 },
  landschaftsschutz: { label: "Landschaftsschutzgebiet", kern: false, abzug: 8, abzugNah: 2 },
  sonstig: { label: "sonstiges Schutzgebiet", kern: false, abzug: 5, abzugNah: 0 },
};

/** Netzknoten-Arten (aus OSM power=substation/transformer bzw. Netzbetreiber-Daten) */
export const KNOTEN_ARTEN = {
  uew: { label: "Umspannwerk Übertragungsnetz (220/380 kV)", kurz: "UW 380/220 kV" },
  uw110: { label: "Umspannwerk 110 kV / Mittelspannung", kurz: "UW 110 kV" },
  ms: { label: "Umspann-/Schaltwerk Mittelspannung", kurz: "UW MS" },
  trafo: { label: "Trafostation (MS/NS)", kurz: "Trafostation" },
};

/** Welche Knoten kommen für eine Ebene in Frage (msLeitung: Einschleifen nahe MS-Netzpunkt) */
const KNOTEN_FUER_EBENE = { msLeitung: ["trafo", "ms", "uw110"], uwMs: ["uw110"], hs: ["uw110", "uew"] };

/** Ertrag kWh/kWp je Bundesland (PVGIS, aus src/data/regionen/*.js – ertrag.kwhProKwp) */
export const ERTRAG = {
  Burgenland: 1210, Kärnten: 1240, Niederösterreich: 1190, Oberösterreich: 1130, Salzburg: 1140, Steiermark: 1220, Tirol: 1370, Vorarlberg: 1130, Wien: 1190,
  _AT: 1120, _DE: 1020, _CH: 1050,
};

/**
 * Widmungsregeln je Bundesland (Stand der Regionaldaten 29.09.2026, src/data/regionen/*.js):
 *   art "uw_radius": Zone = Radius um Umspannwerke (OÖ Kriterienkatalog: energiewirtschaftliche Priorität 1 bis 5 km, 2 bis 7,5 km)
 *   art "zonen":     Zone = verordnete Zonen als Geodaten (NÖ SekRop PV, Bgld. Eignungszonen, Stmk. SAPRO Vorrangzonen)
 *   art "einzelfall": keine landesweite Zonierung – Einzelfallprüfung (Sbg. Kennzeichnung mit Punktesystem, Ktn. max. 4 ha …)
 *   maxHaAusserhalb: Größengrenze außerhalb der Zonen (NÖ 2 ha), maxHa: Obergrenze je Widmung (Ktn. 4 ha)
 */
export const WIDMUNG = {
  Oberösterreich: { art: "uw_radius", zoneKm: 5, angrenzendKm: 7.5, text: "Kriterienkatalog PV-FFA: energiewirtschaftliche Priorität 1 (≤ 5 km zum Umspannwerk) bzw. 2 (≤ 7,5 km); Bodenfruchtbarkeit Stufe 4–5 im Einzelfall prüfen (DORIS)." },
  Niederösterreich: { art: "zonen", angrenzendM: 200, maxHaAusserhalb: 2, text: "SekRop PV: 116 Zonen (je Zone 5 ha, mit Ökologiekonzept 10 ha); außerhalb höchstens 2 ha, Zusammenrechnung im 200-m-Umkreis." },
  Burgenland: { art: "zonen", angrenzendM: 0, maxHaAusserhalb: 0, text: "Freiflächen-PV nur in Eignungszonen (Bgld. RPG 2019 § 22d); unter 10 ha zusätzlich Widmung nötig." },
  Steiermark: { art: "zonen", angrenzendM: 500, text: "SAPRO Solarenergie: 36 Vorrangzonen (> 10 ha); außerhalb Sondernutzung im Freiland über die Gemeinde, Ausschlusszonen beachten." },
  Salzburg: { art: "einzelfall", text: "Kennzeichnung nach § 39b ROG 2009 über 200 m² mit Punktesystem der PV-Kennzeichnungsverordnung 2023 (je Bodenkategorie 20–40 Punkte)." },
  Kärnten: { art: "einzelfall", maxHa: 4, text: "Widmung „Grünland – Photovoltaikanlage“, zusammenhängend max. 4 ha, 1.000 m Abstand zwischen Widmungsflächen (K-PhV 2024)." },
  Tirol: { art: "einzelfall", text: "Sonderfläche bis 250 kWp, darüber Bewilligung nach TEG – Einzelfall." },
  Vorarlberg: { art: "einzelfall", text: "Sondergebiet in der Freifläche; Landesgrünzone Rheintal/Walgau beachten." },
  Wien: { art: "einzelfall", text: "Vorbelastete Flächen bevorzugt; Grünland-Schutzgebiet beachten." },
};

const r1 = (x) => Math.round(x * 10) / 10;
const clamp = (x, a = 0, b = 1) => Math.max(a, Math.min(b, x));

/** Mögliche Leistung in MWp (Freifläche Süd, fest) */
export const mwpFuer = (ha) => r1((Number(ha) || 0) / FREIFLAECHE.haProMwp);

/** Geschätzte Trassenlänge in m aus Luftlinie und Anzahl Querungen */
export function trasseM(luftlinieM, querungen = 0) {
  return Math.round(luftlinieM * TRASSE.umwegFaktor + Math.max(0, querungen) * TRASSE.querungZuschlagM);
}

/** Netzanschlusskosten (Rechner-Logik) für Leistung, Trassenlänge und Kapazität */
export function netzkosten(mwp, trasseKm, { ebene = "auto", kapazitaet = "unbekannt", land = "at" } = {}) {
  const r = rechneNetzanschluss({ mwp: Math.max(0.1, mwp), km: Math.max(0, trasseKm), ebene, kapazitaet: ["frei", "knapp"].includes(kapazitaet) ? kapazitaet : "unbekannt", land });
  return { ebene: r.ebene, summe: Math.round(r.summe), min: Math.round(r.spanne.min), max: Math.round(r.spanne.max), proKwp: Math.round(r.proKwp), anteil: Math.round(r.anteil * 1000) / 1000, ampel: r.ampel, monate: r.monate };
}

/**
 * Bester Netzknoten für eine Fläche: alle geeigneten Knoten im Suchradius, Auswahl nach geschätzten
 * Anschlusskosten (nicht nur Entfernung). `knoten` = [{ id, name, art, spannungKv, kapazitaet, lon, lat }].
 * Liefert { knoten, luftlinieM, trasseM, kosten, ebene } oder null.
 */
export function besterKnoten(punkt, mwp, knoten, { querungen = () => 0, land = "at" } = {}) {
  const ebene = ebeneFuer(mwp);
  const arten = KNOTEN_FUER_EBENE[ebene];
  let best = null;
  for (const k of knoten) {
    if (!arten.includes(k.art)) continue;
    const luft = distanzM(punkt, [k.lon, k.lat]);
    if (luft > TRASSE.suchradiusKm * 1000) continue;
    const tr = trasseM(luft, querungen(k));
    const kosten = netzkosten(mwp, tr / 1000, { ebene: k.art === "trafo" || k.art === "ms" ? "msLeitung" : ebene, kapazitaet: k.kapazitaet, land });
    const strafe = k.kapazitaet === "knapp" ? 1.5 : 1; // knappe Kapazität: Umweg zum nächsten freien Knoten oft günstiger
    const wert = kosten.summe * strafe;
    if (!best || wert < best.wert || (wert === best.wert && luft < best.luftlinieM)) best = { knoten: k, luftlinieM: Math.round(luft), trasseM: tr, kosten, ebene: kosten.ebene, wert };
  }
  if (best) delete best.wert;
  return best;
}

/** Nächster Knoten einer Art (für Anzeige „nächstes Umspannwerk“) */
export function naechsterKnoten(punkt, knoten, arten = ["uw110", "uew"]) {
  let best = null;
  for (const k of knoten) {
    if (!arten.includes(k.art)) continue;
    const d = distanzM(punkt, [k.lon, k.lat]);
    if (!best || d < best.luftlinieM) best = { knoten: k, luftlinieM: Math.round(d) };
  }
  return best;
}

/**
 * Widmungslage je Bundesland. `lage` = { bundesland, uwAbstandKm (nächstes UW ≥ 110 kV), zoneAbstandM (nächste
 * verordnete Zone; 0 = innerhalb; null = keine Zonendaten) }. Liefert { status: zone|angrenzend|ausserhalb|unklar, text }.
 */
export function widmungslage({ bundesland, uwAbstandKm = null, zoneAbstandM = null } = {}) {
  const regel = WIDMUNG[bundesland];
  if (!regel) return { status: "unklar", text: "Keine Widmungsregel hinterlegt – Einzelfallprüfung.", regel: null };
  if (regel.art === "uw_radius") {
    if (uwAbstandKm == null) return { status: "unklar", text: regel.text, regel };
    if (uwAbstandKm <= regel.zoneKm) return { status: "zone", text: `Priorität 1 (≤ ${regel.zoneKm} km zum Umspannwerk). ${regel.text}`, regel };
    if (uwAbstandKm <= regel.angrenzendKm) return { status: "angrenzend", text: `Priorität 2 (≤ ${String(regel.angrenzendKm).replace(".", ",")} km zum Umspannwerk). ${regel.text}`, regel };
    return { status: "ausserhalb", text: `Außerhalb der Prioritätsradien. ${regel.text}`, regel };
  }
  if (regel.art === "zonen") {
    if (zoneAbstandM == null) return { status: "unklar", text: `Zonendaten nicht geladen. ${regel.text}`, regel };
    if (zoneAbstandM <= 0) return { status: "zone", text: `Innerhalb einer verordneten Zone. ${regel.text}`, regel };
    if (regel.angrenzendM && zoneAbstandM <= regel.angrenzendM) return { status: "angrenzend", text: `Angrenzend an eine Zone (${Math.round(zoneAbstandM)} m). ${regel.text}`, regel };
    return { status: "ausserhalb", text: `Außerhalb der Zonen. ${regel.text}`, regel };
  }
  return { status: "unklar", text: regel.text, regel };
}

const SUED = ["S", "SO", "SW", "eben"];

/**
 * Punktwert einer Kandidatenfläche.
 * m = {
 *   ha, kompaktheit (0–1), neigungGrad, exposition (N|NO|O|SO|S|SW|W|NW|eben), nutzung: { acker, gruenland, sonstige } in ha,
 *   schutz: [{ art, anteil (0–1), abstandM }], siedlungAbstandM,
 *   netz: { knoten: { art, kapazitaet }, luftlinieM, trasseM, kosten: { anteil, … } } | null,
 *   widmung: { status, text, regel }, bundesland, land
 * }
 * Liefert { score, ampel, ko[], kriterien[{ id, label, punkte, max, text, art }], mwp }.
 */
export function bewerte(m) {
  const k = [];
  const ko = [];
  const add = (id, label, punkte, max, text, art = punkte >= max * 0.66 ? "plus" : punkte > 0 ? "neutral" : "minus") => k.push({ id, label, punkte: r1(punkte), max, text, art });
  const ha = Number(m.ha) || 0;
  const mwp = mwpFuer(ha);

  // Größe
  let pg;
  if (ha < SCHWELLEN.mindestHa) pg = 0;
  else if (ha < 3) pg = 6;
  else if (ha < SCHWELLEN.idealHa[0]) pg = 6 + ((ha - 3) / 2) * 8;
  else if (ha <= SCHWELLEN.idealHa[1]) pg = 20;
  else pg = 16;
  if (ha < SCHWELLEN.mindestHa) ko.push({ id: "groesse", text: `Unter ${SCHWELLEN.mindestHa} ha – für Freiflächen-PV meist unwirtschaftlich.`, deckel: 25 });
  add("groesse", "Größe", pg, GEWICHTE.groesse, `${r1(ha).toLocaleString("de-DE")} ha${ha > 50 ? " – sehr groß (UVP-Schwelle und Netzkapazität prüfen)" : ha >= 5 ? " – ideale Größe" : ""}`);

  // Form
  const kp = clamp(Number(m.kompaktheit) || 0);
  const pf = clamp((kp - 0.45) / 0.45) * GEWICHTE.form;
  add("form", "Form/Kompaktheit", pf, GEWICHTE.form, kp >= 0.85 ? "kompakt, gut belegbar" : kp >= 0.65 ? "brauchbare Form" : "zerklüftet oder schmal – Belegung eingeschränkt");

  // Neigung/Exposition
  const n = Math.max(0, Number(m.neigungGrad) || 0);
  const exp = m.exposition || "eben";
  const sued = SUED.includes(exp) || n <= 2;
  let pn;
  if (n <= 3) pn = 12;
  else if (n <= 7) pn = sued ? 10 : 6;
  else if (n <= 12) pn = sued ? 6 : 1;
  else pn = sued ? 2 : 0;
  if (n > SCHWELLEN.maxNeigungGrad) ko.push({ id: "neigung", text: `Mittlere Neigung ${r1(n)}° – zu steil für wirtschaftliche Aufständerung.`, deckel: 20 });
  add("neigung", "Neigung/Exposition", pn, GEWICHTE.neigung, `${r1(n).toLocaleString("de-DE")}° im Mittel, ${exp === "eben" ? "eben" : `Exposition ${exp}`}`);

  // Nutzung
  const nu = m.nutzung || {};
  const summe = (nu.acker || 0) + (nu.gruenland || 0) + (nu.sonstige || 0) || 1;
  const pn2 = ((nu.acker || 0) * 8 + (nu.gruenland || 0) * 7 + (nu.sonstige || 0) * 3) / summe;
  const hauptnutzung = (nu.acker || 0) >= (nu.gruenland || 0) ? "Acker" : "Grünland";
  add("nutzung", "Nutzung", pn2, GEWICHTE.nutzung, `${hauptnutzung}${nu.acker && nu.gruenland ? " (gemischt)" : ""} – Agri-PV ${hauptnutzung === "Acker" ? "als Option" : "mit Beweidung möglich"}; EAG-Abschlag 25 % auf Agrarflächen beachten`);

  // Schutzgebiete
  for (const s of m.schutz || []) {
    const def = SCHUTZ_ARTEN[s.art] || SCHUTZ_ARTEN.sonstig;
    const anteil = clamp(Number(s.anteil) || 0);
    if (anteil > 0.05 && def.kern) {
      ko.push({ id: `schutz_${s.art}`, text: `${Math.round(anteil * 100)} % im ${def.label}${s.name ? ` „${s.name}“` : ""} – in der Regel ausgeschlossen.`, deckel: 15 });
      add(`schutz_${s.art}`, def.label, -10, 0, `überdeckt ${Math.round(anteil * 100)} %${s.name ? ` (${s.name})` : ""}`, "ko");
    } else if (anteil > 0.05) {
      add(`schutz_${s.art}`, def.label, -def.abzug * Math.min(1, anteil * 2), 0, `überdeckt ${Math.round(anteil * 100)} %${s.name ? ` (${s.name})` : ""} – Bewilligung erschwert`, "minus");
    } else if ((s.abstandM == null ? Infinity : Number(s.abstandM)) <= 200 && def.abzugNah) {
      add(`schutz_${s.art}`, `Nähe ${def.label}`, -def.abzugNah, 0, `${Math.round(s.abstandM)} m entfernt${s.name ? ` (${s.name})` : ""} – Verträglichkeitsprüfung wahrscheinlich`, "minus");
    }
  }

  // Siedlungsabstand
  const sa = m.siedlungAbstandM == null ? null : Number(m.siedlungAbstandM);
  const [sMin, sVoll] = SCHWELLEN.siedlungAbstandM;
  const ps = sa == null ? 4 : sa < sMin ? 0 : sa >= sVoll ? 8 : 4 + ((sa - sMin) / (sVoll - sMin)) * 4;
  add("siedlung", "Abstand Siedlung", ps, GEWICHTE.siedlung, sa == null ? "unbekannt" : `${Math.round(sa).toLocaleString("de-DE")} m zur nächsten Siedlung${sa < sMin ? " – Blendung/Akzeptanz kritisch" : ""}`);

  // Netz: Trassenlänge
  const netz = m.netz;
  if (netz) {
    const km = netz.trasseM / 1000;
    const pnetz = km <= 1 ? 22 : km <= 3 ? 22 - ((km - 1) / 2) * 4 : km <= 5 ? 18 - ((km - 3) / 2) * 5 : km <= 8 ? 13 - ((km - 5) / 3) * 6 : km <= 12 ? 7 - ((km - 8) / 4) * 4 : Math.max(0, 3 - (km - 12) / 4);
    const kn = netz.knoten || {};
    add("netz", "Netzanschluss (Trasse)", pnetz, GEWICHTE.netz, `${r1(km).toLocaleString("de-DE")} km geschätzte Trasse (Luftlinie ${r1(netz.luftlinieM / 1000).toLocaleString("de-DE")} km) zu ${kn.name || KNOTEN_ARTEN[kn.art]?.kurz || "Netzknoten"}`);
    if (kn.kapazitaet === "knapp") add("kapazitaet", "Netzkapazität", -8, 0, "Kapazität laut Netzbetreiber knapp – Ausbau/Wartezeit wahrscheinlich", "minus");
    else if (kn.kapazitaet === "frei") add("kapazitaet", "Netzkapazität", 3, 0, "freie Einspeisekapazität veröffentlicht", "plus");
    const anteil = netz.kosten?.anteil ?? 1;
    const pk = anteil < 0.08 ? 8 : anteil < 0.15 ? 8 - ((anteil - 0.08) / 0.07) * 3 : anteil < 0.25 ? 5 - ((anteil - 0.15) / 0.1) * 3 : Math.max(0, 2 - (anteil - 0.25) * 10);
    add("kosten", "Netzanschlusskosten", pk, GEWICHTE.kosten, `≈ ${Math.round(anteil * 100)} % der Anlagenkosten (${Math.round((netz.kosten?.proKwp || 0))} €/kWp)`);
  } else {
    add("netz", "Netzanschluss (Trasse)", 0, GEWICHTE.netz, `kein geeigneter Netzknoten im Umkreis von ${TRASSE.suchradiusKm} km`, "minus");
    add("kosten", "Netzanschlusskosten", 0, GEWICHTE.kosten, "nicht bestimmbar", "minus");
  }

  // Widmung
  const w = m.widmung || { status: "unklar" };
  const pw = { zone: 10, angrenzend: 6, unklar: 4, ausserhalb: 2 }[w.status] ?? 4;
  add("widmung", "Widmungslage", pw, GEWICHTE.widmung, { zone: "in Zone/Priorität 1", angrenzend: "angrenzend/Priorität 2", ausserhalb: "außerhalb der Zonen", unklar: "Einzelfallprüfung" }[w.status] || "Einzelfallprüfung");
  const regel = w.regel || WIDMUNG[m.bundesland];
  if (regel?.maxHaAusserhalb !== undefined && w.status !== "zone" && ha > regel.maxHaAusserhalb) {
    ko.push({ id: "widmung", text: regel.maxHaAusserhalb > 0 ? `Außerhalb der Zonen nur bis ${regel.maxHaAusserhalb} ha widmungsfähig.` : "Außerhalb der Eignungszonen nicht zulässig.", deckel: regel.maxHaAusserhalb > 0 ? 45 : 20 });
  }
  if (regel?.maxHa && ha > regel.maxHa) add("widmung_max", "Widmungsgrenze", -3, 0, `je Widmung höchstens ${regel.maxHa} ha – Teilfläche oder Ausnahme`, "minus");

  // Einstrahlung
  const ertrag = ERTRAG[m.bundesland] || ERTRAG[`_${m.land || "AT"}`] || ERTRAG._AT;
  const pe = clamp((ertrag - 1000) / 200) * GEWICHTE.einstrahlung;
  add("einstrahlung", "Einstrahlung", pe, GEWICHTE.einstrahlung, `≈ ${ertrag.toLocaleString("de-DE")} kWh/kWp und Jahr`);

  let score = k.reduce((s, x) => s + x.punkte, 0);
  score = Math.max(0, Math.min(100, score));
  for (const x of ko) score = Math.min(score, x.deckel);
  score = Math.round(score);
  const ampel = score >= SCHWELLEN.ampel.gruen ? "gruen" : score >= SCHWELLEN.ampel.gelb ? "gelb" : "rot";
  return { score, ampel, ko, kriterien: k, mwp, ertragKwhProKwp: ertrag };
}

/** Kennzahlen für den Steckbrief (Ertrag, Pacht, Netzkosten) */
export function kennzahlen(ha, { ertragKwhProKwp = ERTRAG._AT, agri = false } = {}) {
  const mwp = mwpFuer(ha);
  const p = agri ? PACHT.agriProHa : PACHT.freiflaecheProHa;
  return {
    mwp,
    ertragMwh: Math.round(mwp * ertragKwhProKwp),
    pachtJahr: { min: Math.round(ha * p.min), mittel: Math.round(ha * p.mittel), max: Math.round(ha * p.max) },
    pachtProHa: p,
    capex: { min: Math.round(mwp * 1000 * FREIFLAECHE.capexProKwp.min), max: Math.round(mwp * 1000 * FREIFLAECHE.capexProKwp.max) },
  };
}

/** Priorität A/B/C (wie Akquise-Pipeline) */
export function prioritaet(score, ha) {
  if (score >= 65 && (Number(ha) || 0) >= 5) return "A";
  if (score >= 45) return "B";
  return "C";
}

// src/lib/plattform/geodaten/kandidaten.js
//
// Kandidatenflächen aus Parzellen/Schlägen bilden und bewerten (reine Funktionen, ohne Datei- oder Netzzugriff).
// Genutzt vom Demo-Adapter (lokale GeoJSON-Dateien); im Betrieb liefert der Geodaten-Dienst dieselbe Struktur
// (PostGIS: ST_ClusterDBSCAN(eps = 0) über geeignete Parzellen, Kennzahlen in EPSG:31287).
//
// Kandidat = zusammenhängender Verbund geeigneter Parzellen (Acker/Grünland; Wald/Gewässer trennen). Mehrere
// Eigentümer sind möglich – die Akquise sichert dann mehrere Parzellen (Steckbrief listet sie einzeln).

import { abstandPolygonPolygonM, abstandPunktPolygonM, bbox, bboxSchneidet, distanzM, flaecheM2, kompaktheit, schwerpunkt, ueberdeckung } from "./geo.js";
import { besterKnoten, bewerte, kennzahlen, mwpFuer, naechsterKnoten, netzkosten, prioritaet, widmungslage } from "./scoring.js";

const GEEIGNET = ["acker", "gruenland"];
const NACHBAR_M = 3; // Parzellen mit weniger als 3 m Abstand gelten als zusammenhängend (Feldweg-Grenzen ausgenommen)

function erweitert(b, m) {
  const dLat = m / 111320;
  const dLon = m / (111320 * Math.cos(((b[1] + b[3]) / 2) * (Math.PI / 180)));
  return [b[0] - dLon, b[1] - dLat, b[2] + dLon, b[3] + dLat];
}

const mehrheit = (werte) => {
  const z = new Map();
  for (const [w, g] of werte) z.set(w, (z.get(w) || 0) + g);
  return [...z.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? "";
};

/** Zusammenhängende Verbünde (Union-Find über Nachbarschaft) */
export function verbuende(parzellen) {
  const n = parzellen.length;
  const eltern = parzellen.map((_, i) => i);
  const wurzel = (i) => (eltern[i] === i ? i : (eltern[i] = wurzel(eltern[i])));
  const boxen = parzellen.map((p) => erweitert(bbox(p.geometry), NACHBAR_M));
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      if (!bboxSchneidet(boxen[i], boxen[j])) continue;
      if (abstandPolygonPolygonM(parzellen[i].geometry, parzellen[j].geometry) <= NACHBAR_M) eltern[wurzel(i)] = wurzel(j);
    }
  }
  const gruppen = new Map();
  parzellen.forEach((p, i) => {
    const w = wurzel(i);
    if (!gruppen.has(w)) gruppen.set(w, []);
    gruppen.get(w).push(p);
  });
  return [...gruppen.values()];
}

/** Knoten-Feature → flaches Objekt */
export const knotenFlach = (f) => ({ ...f.properties, lon: f.geometry.coordinates[0], lat: f.geometry.coordinates[1] });

/**
 * Kandidaten bauen und bewerten.
 * daten = { parzellen: Feature[], knoten: Feature[], schutz: Feature[], orte: Feature[], zonen?: Feature[] }
 */
export function kandidatenBauen({ parzellen = [], knoten = [], schutz = [], orte = [], zonen = [] }) {
  const geeignet = parzellen.filter((p) => GEEIGNET.includes(p.properties?.nutzung));
  const kn = knoten.map(knotenFlach);
  const schutzBoxen = schutz.map((s) => bbox(s.geometry));
  const zonenBoxen = zonen.map((z) => bbox(z.geometry));
  const ergebnis = [];

  for (const gruppe of verbuende(geeignet)) {
    gruppe.sort((a, b) => String(a.properties.id).localeCompare(String(b.properties.id)));
    const flaechen = gruppe.map((p) => p.properties.flaecheM2 || flaecheM2(p.geometry));
    const m2 = flaechen.reduce((s, x) => s + x, 0);
    const ha = Math.round((m2 / 10000) * 100) / 100;
    const geometrie = { type: "MultiPolygon", coordinates: gruppe.map((p) => (p.geometry.type === "Polygon" ? p.geometry.coordinates : p.geometry.coordinates[0])) };
    const box = bbox(geometrie);
    const sp = gruppe.map((p) => schwerpunkt(p.geometry));
    const mitte = [sp.reduce((s, q, i) => s + q[0] * flaechen[i], 0) / m2, sp.reduce((s, q, i) => s + q[1] * flaechen[i], 0) / m2];
    const gewicht = (f) => gruppe.map((p, i) => [f(p.properties), flaechen[i]]);
    const neigung = gruppe.reduce((s, p, i) => s + (Number(p.properties.neigungGrad) || 0) * flaechen[i], 0) / m2;
    const nutzung = { acker: 0, gruenland: 0, sonstige: 0 };
    gruppe.forEach((p, i) => (nutzung[p.properties.nutzung === "acker" ? "acker" : p.properties.nutzung === "gruenland" ? "gruenland" : "sonstige"] += flaechen[i] / 10000));
    const bundesland = mehrheit(gewicht((p) => p.bundesland || ""));
    const land = mehrheit(gewicht((p) => p.land || "AT"));

    // Schutzgebiete: Überdeckung (flächengewichtet) und Abstand
    const nahBox = erweitert(box, 300);
    const schutzListe = [];
    schutz.forEach((s, i) => {
      if (!bboxSchneidet(nahBox, schutzBoxen[i])) return;
      let anteil = 0;
      let abstand = Infinity;
      gruppe.forEach((p, j) => {
        anteil += ueberdeckung(p.geometry, s.geometry) * flaechen[j];
        abstand = Math.min(abstand, abstandPolygonPolygonM(p.geometry, s.geometry));
      });
      anteil /= m2;
      if (abstand <= 300 || anteil > 0) schutzListe.push({ id: s.properties.id, name: s.properties.name, art: s.properties.art, anteil: Math.round(anteil * 100) / 100, abstandM: Math.round(abstand) });
    });

    // Siedlungsabstand: Siedlungspunkt minus Näherungsradius
    let siedlung = null;
    for (const o of orte) {
      const pt = o.geometry.coordinates;
      if (distanzM(pt, mitte) > 4000) continue;
      const d = Math.min(...gruppe.map((p) => abstandPunktPolygonM(pt, p.geometry))) - (o.properties.radiusM || 0);
      if (!siedlung || d < siedlung.abstandM) siedlung = { name: o.properties.name, typ: o.properties.typ, abstandM: Math.max(0, Math.round(d)) };
    }

    // Netz
    const mwp = mwpFuer(ha);
    const netz = besterKnoten(mitte, mwp, kn, { land: land === "AT" ? "at" : land.toLowerCase() });
    const uw = naechsterKnoten(mitte, kn, ["uw110", "uew"]);

    // Widmung (Zonen, wenn als Geodaten vorhanden)
    let zoneAbstandM = zonen.length ? Infinity : null;
    zonen.forEach((z, i) => {
      if (!bboxSchneidet(erweitert(box, 1000), zonenBoxen[i])) return;
      for (const p of gruppe) zoneAbstandM = Math.min(zoneAbstandM, ueberdeckung(p.geometry, z.geometry) > 0.5 ? 0 : abstandPolygonPolygonM(p.geometry, z.geometry));
    });
    if (zoneAbstandM === Infinity) zoneAbstandM = 1e9;
    const widmung = widmungslage({ bundesland, uwAbstandKm: uw ? uw.luftlinieM / 1000 : null, zoneAbstandM });

    const m = {
      ha,
      kompaktheit: kompaktheit(gruppe.map((p) => p.geometry), m2),
      neigungGrad: Math.round(neigung * 10) / 10,
      exposition: mehrheit(gewicht((p) => p.exposition || "eben")),
      nutzung,
      schutz: schutzListe,
      siedlungAbstandM: siedlung?.abstandM ?? null,
      netz,
      widmung,
      bundesland,
      land,
    };
    const b = bewerte(m);
    const agri = nutzung.acker >= nutzung.gruenland;
    ergebnis.push({
      id: `K-${gruppe[0].properties.id}`,
      demo: gruppe.some((p) => p.properties.demo),
      ha,
      mwp,
      score: b.score,
      ampel: b.ampel,
      prioritaet: prioritaet(b.score, ha),
      ko: b.ko,
      kriterien: b.kriterien,
      schwerpunkt: [Math.round(mitte[0] * 1e6) / 1e6, Math.round(mitte[1] * 1e6) / 1e6],
      bbox: box.map((x) => Math.round(x * 1e6) / 1e6),
      geometrie,
      land,
      bundesland,
      bezirk: mehrheit(gewicht((p) => p.bezirk || "")),
      gemeinde: mehrheit(gewicht((p) => p.gemeinde || "")),
      kg: [...new Set(gruppe.map((p) => p.properties.kg))],
      parzellen: gruppe.map((p, i) => ({ id: p.properties.id, kg: p.properties.kg, kgNr: p.properties.kgNr, gstNr: p.properties.gstNr, ha: Math.round(flaechen[i] / 100) / 100, nutzung: p.properties.nutzung, kultur: p.properties.kultur || "" })),
      merkmale: {
        kompaktheit: m.kompaktheit,
        neigungGrad: m.neigungGrad,
        exposition: m.exposition,
        nutzung: { acker: Math.round(nutzung.acker * 100) / 100, gruenland: Math.round(nutzung.gruenland * 100) / 100 },
        hauptnutzung: agri ? "acker" : "gruenland",
        siedlung,
        schutz: schutzListe,
      },
      netz: netz
        ? {
            knoten: { id: netz.knoten.id, name: netz.knoten.name, art: netz.knoten.art, spannungKv: netz.knoten.spannungKv, betreiber: netz.knoten.betreiber || "", kapazitaet: netz.knoten.kapazitaet || "unbekannt", lon: netz.knoten.lon, lat: netz.knoten.lat },
            luftlinieM: netz.luftlinieM,
            trasseM: netz.trasseM,
            ebene: netz.ebene,
            kosten: netz.kosten,
            kapazitaetAmpel: netz.knoten.kapazitaet === "frei" ? "gruen" : netz.knoten.kapazitaet === "knapp" ? "rot" : "gelb",
          }
        : null,
      umspannwerk: uw ? { id: uw.knoten.id, name: uw.knoten.name, art: uw.knoten.art, spannungKv: uw.knoten.spannungKv, luftlinieM: uw.luftlinieM, lon: uw.knoten.lon, lat: uw.knoten.lat, kosten: netzkosten(mwp, (uw.luftlinieM * 1.25) / 1000, { kapazitaet: uw.knoten.kapazitaet }) } : null,
      widmung: { status: widmung.status, text: widmung.text },
      kennzahlen: kennzahlen(ha, { ertragKwhProKwp: b.ertragKwhProKwp, agri: false }),
      kennzahlenAgri: kennzahlen(ha, { ertragKwhProKwp: b.ertragKwhProKwp, agri: true }),
    });
  }
  ergebnis.sort((a, b) => b.score - a.score || b.ha - a.ha);
  return ergebnis;
}

/** Filter auf Kandidatenliste (gleiche Parameter wie die Dienst-API) */
export function filtern(liste, { bbox: box, minHa, maxTrasseKm, minScore, bundesland, bezirk, gemeinde, ampel, q } = {}) {
  let l = liste;
  if (box) l = l.filter((k) => bboxSchneidet(k.bbox, box));
  if (minHa) l = l.filter((k) => k.ha >= minHa);
  if (maxTrasseKm) l = l.filter((k) => k.netz && k.netz.trasseM <= maxTrasseKm * 1000);
  if (minScore) l = l.filter((k) => k.score >= minScore);
  if (bundesland) l = l.filter((k) => k.bundesland === bundesland);
  if (bezirk) l = l.filter((k) => k.bezirk === bezirk);
  if (gemeinde) l = l.filter((k) => k.gemeinde === gemeinde);
  if (ampel) l = l.filter((k) => k.ampel === ampel);
  if (q) {
    const s = String(q).toLowerCase();
    l = l.filter((k) => [k.id, k.gemeinde, k.bezirk, ...k.kg, ...k.parzellen.map((p) => `${p.kgNr} ${p.gstNr}`)].join(" ").toLowerCase().includes(s));
  }
  return l;
}

/** Beste Flächen im Umkreis X km um einen Netzknoten */
export function imUmkreis(liste, knoten, km) {
  const mitte = [knoten.lon, knoten.lat];
  return liste
    .map((k) => ({ ...k, abstandZumKnotenM: Math.round(distanzM(k.schwerpunkt, mitte)) }))
    .filter((k) => k.abstandZumKnotenM <= km * 1000)
    .sort((a, b) => b.score - a.score || a.abstandZumKnotenM - b.abstandZumKnotenM);
}
// src/lib/plattform/geodaten/demo.js
//
// Demo-Implementierung des Geodaten-Adapters: liest die lokalen GeoJSON-Dateien SYNCHRON (readFileSync – keine
// awaited Dateizugriffe beim Rendern) und rechnet mit derselben Scoring-Logik wie der Dienst (kandidaten.js).
//   public/geo/netzknoten-ooe-sbg.geojson        OSM power=substation/transformer (ODbL), Stand Overpass 30.09.2026
//   public/geo/schutzgebiete-innviertel.geojson  OSM Schutzgebiete (ODbL) – nicht amtlich
//   public/geo/orte-innviertel.geojson           OSM Siedlungspunkte (ODbL)
//   src/data/geo/parzellen-demo.geojson          SYNTHETISCHE Parzellen (DEMO, keine echten Grundstücke/Eigentümer)
// Erzeugt mit Backend-Import/dienste/geodaten/demo/demo_bauen.py. Nur serverseitig verwenden.

import { readFileSync, statSync } from "node:fs";
import path from "node:path";
import { bbox as bboxVon, bboxSchneidet, kreis } from "./geo.js";
import { filtern, imUmkreis, kandidatenBauen, knotenFlach } from "./kandidaten.js";
import { KNOTEN_ARTEN, SCORING_VERSION } from "./scoring.js";

const DATEIEN = {
  parzellen: "src/data/geo/parzellen-demo.geojson",
  knoten: "public/geo/netzknoten-ooe-sbg.geojson",
  schutz: "public/geo/schutzgebiete-innviertel.geojson",
  orte: "public/geo/orte-innviertel.geojson",
};

let roh = null;
let cache = null;

function lesen() {
  const pfade = Object.fromEntries(Object.entries(DATEIEN).map(([k, p]) => [k, path.join(process.cwd(), p)]));
  const stempel = Object.values(pfade).map((p) => statSync(p).mtimeMs).join("|");
  if (!roh || roh.stempel !== stempel) {
    const j = (p) => JSON.parse(readFileSync(p, "utf8"));
    const d = Object.fromEntries(Object.entries(pfade).map(([k, p]) => [k, j(p)]));
    roh = { stempel, ...d };
    cache = null;
  }
  return roh;
}

/** Netzknoten mit gepflegten Kapazitäten überlagern */
function knotenMitKapazitaet(features, kap = {}) {
  return features.map((f) => {
    const k = kap[f.properties.id];
    return k ? { ...f, properties: { ...f.properties, kapazitaet: k.kapazitaet, freiMw: k.freiMw ?? null, kapazitaetQuelle: k.quelle, kapazitaetStand: k.stand } } : f;
  });
}

function daten(kapazitaeten = {}) {
  const r = lesen();
  const schluessel = `${r.stempel}#${JSON.stringify(kapazitaeten)}`;
  if (!cache || cache.schluessel !== schluessel) {
    const knoten = knotenMitKapazitaet(r.knoten.features, kapazitaeten);
    const kandidaten = kandidatenBauen({ parzellen: r.parzellen.features, knoten, schutz: r.schutz.features, orte: r.orte.features });
    cache = { schluessel, knoten, kandidaten };
  }
  return cache;
}

const QUELLEN = () => {
  const r = lesen();
  return [
    { id: "osm_netz", titel: "Umspannwerke/Trafostationen (OpenStreetMap)", lizenz: "ODbL-1.0", attribution: "© OpenStreetMap-Mitwirkende (ODbL)", url: "https://www.openstreetmap.org/copyright", stand: r.knoten.metadata?.stand || null },
    { id: "osm_schutz", titel: "Schutzgebiete (OpenStreetMap, nicht amtlich)", lizenz: "ODbL-1.0", attribution: "© OpenStreetMap-Mitwirkende (ODbL)", url: "https://www.openstreetmap.org/copyright", stand: r.schutz.metadata?.stand || null },
    { id: "demo", titel: "Parzellen (SYNTHETISCH – DEMO)", lizenz: "intern", attribution: "DEMO-Parzellen, keine echten Grundstücke", url: "", stand: r.parzellen.metadata?.stand || null },
    { id: "basemap", titel: "basemap.at", lizenz: "CC-BY-4.0", attribution: "Grundkarte: basemap.at", url: "https://basemap.at", stand: null },
  ];
};

const zaehle = (liste, feld) => [...liste.reduce((m, k) => m.set(k[feld], (m.get(k[feld]) || 0) + 1), new Map()).entries()].filter(([x]) => x).sort((a, b) => a[0].localeCompare(b[0], "de")).map(([name, anzahl]) => ({ name, anzahl }));

export function uebersicht({ kapazitaeten } = {}) {
  const { kandidaten } = daten(kapazitaeten);
  const summe = (f) => Math.round(kandidaten.reduce((s, k) => s + (Number(f(k)) || 0), 0) * 10) / 10;
  return {
    modus: "demo",
    version: SCORING_VERSION,
    quellen: QUELLEN(),
    kennzahlen: {
      kandidaten: kandidaten.length,
      ha: summe((k) => k.ha),
      mwp: summe((k) => k.mwp),
      gruen: kandidaten.filter((k) => k.ampel === "gruen").length,
      prioA: kandidaten.filter((k) => k.prioritaet === "A").length,
    },
    gebiete: { bundeslaender: zaehle(kandidaten, "bundesland"), bezirke: zaehle(kandidaten, "bezirk"), gemeinden: zaehle(kandidaten, "gemeinde") },
    start: { mitte: [13.19, 48.17], zoom: 10 },
  };
}

export function kandidaten(filter = {}, { kapazitaeten } = {}) {
  const liste = filtern(daten(kapazitaeten).kandidaten, filter);
  return { kandidaten: liste.slice(0, Math.min(2000, filter.limit || 500)), anzahl: liste.length, version: SCORING_VERSION };
}

export function kandidat(id, { kapazitaeten } = {}) {
  return daten(kapazitaeten).kandidaten.find((k) => k.id === id) || null;
}

export function umkreis(knotenId, km, { kapazitaeten } = {}) {
  const d = daten(kapazitaeten);
  const f = d.knoten.find((x) => x.properties.id === knotenId);
  if (!f) return null;
  const liste = imUmkreis(d.kandidaten, knotenFlach(f), km);
  return { knoten: knotenFlach(f), km, kandidaten: liste, anzahl: liste.length };
}

export function netzknoten({ bbox, arten = ["uew", "uw110", "ms", "trafo"] } = {}, { kapazitaeten } = {}) {
  const d = daten(kapazitaeten);
  const features = d.knoten.filter((f) => arten.includes(f.properties.art) && (!bbox || bboxSchneidet(bboxVon(f.geometry), bbox)));
  return { type: "FeatureCollection", features };
}

/** Ebenen: schutzgebiete (OSM) | zonen (OÖ-Prioritätsradien um Umspannwerke, abgeleitet aus dem Kriterienkatalog) */
export function ebene(name, { bbox } = {}) {
  const r = lesen();
  if (name === "schutzgebiete") {
    return { type: "FeatureCollection", features: r.schutz.features.filter((f) => !bbox || bboxSchneidet(bboxVon(f.geometry), bbox)) };
  }
  if (name === "zonen") {
    // Näherung für die Demo: Knoten nördlich 48,0° und östlich 12,75° liegen im Demogebiet in Oberösterreich
    const uws = r.knoten.features.filter((f) => ["uw110", "uew"].includes(f.properties.art)).filter((f) => f.geometry.coordinates[1] >= 48.0 && f.geometry.coordinates[0] >= 12.75 && f.geometry.coordinates[0] <= 14.2);
    const features = [];
    for (const u of uws) {
      if (bbox && !bboxSchneidet([u.geometry.coordinates[0] - 0.12, u.geometry.coordinates[1] - 0.08, u.geometry.coordinates[0] + 0.12, u.geometry.coordinates[1] + 0.08], bbox)) continue;
      features.push({ type: "Feature", geometry: kreis(u.geometry.coordinates, 7500), properties: { id: `p2-${u.properties.id}`, name: `Priorität 2 – ${u.properties.name || "Umspannwerk"}`, art: "ooe_prioritaet_2", bundesland: "Oberösterreich" } });
      features.push({ type: "Feature", geometry: kreis(u.geometry.coordinates, 5000), properties: { id: `p1-${u.properties.id}`, name: `Priorität 1 – ${u.properties.name || "Umspannwerk"}`, art: "ooe_prioritaet_1", bundesland: "Oberösterreich" } });
    }
    return { type: "FeatureCollection", features, hinweis: "Abgeleitet: OÖ Kriterienkatalog PV-FFA – energiewirtschaftliche Priorität 1 (≤ 5 km) und 2 (≤ 7,5 km) um Umspannwerke. Keine amtliche Zonenkarte." };
  }
  return null;
}

/** Suche: Gemeinde/Ort, KG, Grundstücksnummer (KG-Nr Gst-Nr), Umspannwerk, Kandidaten-ID */
export function suche(q, { kapazitaeten } = {}) {
  const s = String(q || "").trim().toLowerCase();
  if (s.length < 2) return { treffer: [] };
  const r = lesen();
  const d = daten(kapazitaeten);
  const treffer = [];
  for (const k of d.kandidaten) {
    if (treffer.length >= 6) break;
    if (k.id.toLowerCase().includes(s) || k.gemeinde.toLowerCase().includes(s) || k.kg.some((x) => x.toLowerCase().includes(s))) {
      treffer.push({ typ: "kandidat", label: `${k.gemeinde} · ${String(k.ha).replace(".", ",")} ha · Score ${k.score}`, kandidatId: k.id, lon: k.schwerpunkt[0], lat: k.schwerpunkt[1] });
    }
  }
  const gst = s.match(/^(\d{5})\s*[-/ ]\s*([\d/.]+)$/);
  for (const p of r.parzellen.features) {
    if (treffer.length >= 10) break;
    const pr = p.properties;
    if ((gst && pr.kgNr === gst[1] && pr.gstNr === gst[2]) || (!gst && `${pr.kgNr} ${pr.gstNr}`.includes(s) && /\d/.test(s))) {
      const c = bboxVon(p.geometry);
      treffer.push({ typ: "grundstueck", label: `${pr.kg} (${pr.kgNr}), Gst. ${pr.gstNr}`, parzelleId: pr.id, lon: (c[0] + c[2]) / 2, lat: (c[1] + c[3]) / 2 });
    }
  }
  for (const f of d.knoten) {
    if (treffer.length >= 14) break;
    if (f.properties.art !== "trafo" && f.properties.name && f.properties.name.toLowerCase().includes(s)) {
      treffer.push({ typ: "netzknoten", label: `${f.properties.name} (${KNOTEN_ARTEN[f.properties.art].kurz})`, knotenId: f.properties.id, lon: f.geometry.coordinates[0], lat: f.geometry.coordinates[1] });
    }
  }
  for (const o of r.orte.features) {
    if (treffer.length >= 20) break;
    if (["town", "village", "city"].includes(o.properties.typ) && o.properties.name.toLowerCase().startsWith(s)) {
      treffer.push({ typ: "ort", label: o.properties.name, lon: o.geometry.coordinates[0], lat: o.geometry.coordinates[1] });
    }
  }
  return { treffer };
}

// src/lib/plattform/geodaten/index.js
//
// Geodaten-Adapter für das Akquise-Cockpit (nur serverseitig). Auswahl:
//   GEODATEN_URL + GEODATEN_TOKEN gesetzt → Geodaten-Dienst (Backend-Import/dienste/geodaten, PostGIS)
//   sonst                              → Demo (lokale GeoJSON-Dateien, gleiche Scoring-Logik; im Produktions-Build nur
//                                         mit PLATTFORM_DEMO=1, sonst 503)
// Rechte: Backoffice-Bereich „geodaten“ (Rechte-Matrix: Leitung und Akquise). Jede Operation prüft selbst – die Route
// prüft vorab (server/route.js → adminRechtPruefen).
//
// Operationen (n = angemeldeter Nutzer):
//   uebersicht(n) · kandidaten(n, filter) · kandidat(n, id) · umkreis(n, knotenId, km) · netzknoten(n, { bbox, arten })
//   ebene(n, name, { bbox }) · suche(n, q) · kapazitaetSetzen(n, knotenId, daten) · uebernehmen(n, kandidatId, { notiz })

import * as demo from "./demo";
import * as dienst from "./dienst";
import { geodatenBackend } from "../backend/geodaten";
import { PlattformFehler } from "../fehler";
import { BEREICHE, STUFE_LABEL, stufe } from "../rechte";
import { KONFIG_FEHLER } from "../backend";

export function geodatenModus() {
  if (dienst.dienstKonfiguriert()) return "dienst";
  if (process.env.NODE_ENV === "production" && process.env.PLATTFORM_DEMO !== "1") return null;
  return "demo";
}

function recht(n, st = 1) {
  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
  if (!n.rollen?.includes("admin")) throw new PlattformFehler(403, "Nur für das Backoffice.");
  if (stufe(n, "geodaten") < st) throw new PlattformFehler(403, `Ihre Backoffice-Rolle erlaubt im Bereich „${BEREICHE.geodaten}“ kein ${STUFE_LABEL[st]}.`, "recht");
}

function modusPflicht() {
  const m = geodatenModus();
  if (!m) throw new PlattformFehler(503, KONFIG_FEHLER);
  return m;
}

/** Im Demo-Betrieb: gepflegte Kapazitäten aus dem Plattform-Backend (Dienst hält sie selbst) */
async function kontext(n) {
  if (modusPflicht() === "dienst") return { nutzer: n };
  return { nutzer: n, kapazitaeten: await geodatenBackend().netzkapazitaeten(n) };
}

export async function uebersicht(n) {
  recht(n, 1);
  const k = await kontext(n);
  return modusPflicht() === "dienst" ? dienst.uebersicht(k) : demo.uebersicht(k);
}

/** Filter aus Suchparametern (URLSearchParams) lesen und begrenzen */
export function filterLesen(suche, bboxLesen) {
  const zahl = (name, max) => {
    const x = Number(String(suche.get(name) || "").replace(",", "."));
    return Number.isFinite(x) && x > 0 ? Math.min(x, max) : undefined;
  };
  const text = (name) => (suche.get(name) || "").slice(0, 80) || undefined;
  const ampel = ["gruen", "gelb", "rot"].includes(suche.get("ampel")) ? suche.get("ampel") : undefined;
  return {
    bbox: bboxLesen(suche.get("bbox")) || undefined,
    minHa: zahl("minHa", 1000),
    maxTrasseKm: zahl("maxTrasseKm", 50),
    minScore: zahl("minScore", 100),
    bundesland: text("bundesland"),
    bezirk: text("bezirk"),
    gemeinde: text("gemeinde"),
    ampel,
    q: text("q"),
    limit: zahl("limit", 2000),
  };
}

export async function kandidaten(n, filter = {}) {
  recht(n, 1);
  const k = await kontext(n);
  return modusPflicht() === "dienst" ? dienst.kandidaten(filter, k) : demo.kandidaten(filter, k);
}

export async function kandidat(n, id) {
