  const r = modusPflicht() === "dienst" ? await dienst.kandidat(id, k) : demo.kandidat(id, k);
  if (!r) throw new PlattformFehler(404, "Kandidatenfläche nicht gefunden.");
  return r;
}

export async function umkreis(n, knotenId, km) {
  recht(n, 1);
