  const k = await kontext(n);
  const r = modusPflicht() === "dienst" ? await dienst.umkreis(knotenId, radius, k) : demo.umkreis(knotenId, radius, k);
  if (!r) throw new PlattformFehler(404, "Netzknoten nicht gefunden.");
