  { gruppe: "Allgemein", schluessel: "portal.link", text: "Link ins Portal zum Objekt", beispiel: "https://www.oekoinvest.com/portal" },
  { gruppe: "Allgemein", schluessel: "heute", text: "Heutiges Datum", beispiel: "30.09.2026" },
];
export const PLATZHALTER_SCHLUESSEL = new Set(PLATZHALTER.map((p) => p.schluessel));

const MUSTER = /\{\{\s*([a-zA-Z][a-zA-Z0-9_.]{0,60})\s*\}\}/g;

function aufloesen(kontext, schluessel) {
  let v = kontext;
  for (const t of schluessel.split(".")) {
    if (v === null || v === undefined || typeof v !== "object" || !Object.prototype.hasOwnProperty.call(v, t)) return undefined;
    v = v[t];
  }
  if (v === null || v === undefined) return "";
  if (typeof v === "number") return Number.isInteger(v) ? String(v) : v.toLocaleString("de-DE", { maximumFractionDigits: 1 });
  if (typeof v === "object") return undefined;
  return String(v);
}

/** Platzhalter im Text finden */
export function platzhalterIn(text) {
  return [...String(text || "").matchAll(MUSTER)].map((m) => m[1]);
}

/**
 * Text rendern. Liefert { text, unbekannt: [..], leer: [..] }:
 * unbekannt = Platzhalter, die es nicht gibt; leer = bekannte ohne Wert (z. B. keine Fläche am Vorgang).
 */
export function rendern(vorlagenText, kontext = {}) {
  const unbekannt = new Set();
  const leer = new Set();
  const text = String(vorlagenText || "").replace(MUSTER, (_, k) => {
    if (!PLATZHALTER_SCHLUESSEL.has(k)) {
      unbekannt.add(k);
      return "";
    }
    const v = aufloesen(kontext, k);
    if (v === undefined || v === "") {
      leer.add(k);
      return "";
    }
    return v;
  });
  return { text: text.replace(/[ \t]+\n/g, "\n").replace(/\n{3,}/g, "\n\n"), unbekannt: [...unbekannt], leer: [...leer] };
}

/** Beispielkontext für die Vorschau ohne Objekt */
export function beispielKontext() {
  const k = {};
  for (const p of PLATZHALTER) {
    const teile = p.schluessel.split(".");
    let z = k;
    teile.forEach((t, i) => {
      if (i === teile.length - 1) z[t] = p.beispiel;
      else z = z[t] = z[t] || {};
    });
  }
  return k;
}

/** Vorlage prüfen (Server): Pflichtfelder, unbekannte Platzhalter → Fehlermeldung oder "" */
export function vorlageFehler({ name, kanal, betreff, text }) {
  if (!name || String(name).trim().length < 3) return "Bitte einen Namen (mind. 3 Zeichen) angeben.";
  if (!VORLAGE_KANAELE[kanal]) return "Unbekannter Kanal.";
  if (kanal === "email" && (!betreff || String(betreff).trim().length < 3)) return "Bitte einen Betreff angeben.";
  if (!text || String(text).trim().length < 10) return "Der Text ist zu kurz (mind. 10 Zeichen).";
  const unbekannt = [...platzhalterIn(betreff), ...platzhalterIn(text)].filter((k) => !PLATZHALTER_SCHLUESSEL.has(k));
  if (unbekannt.length) return `Unbekannte Platzhalter: ${[...new Set(unbekannt)].map((k) => `{{${k}}}`).join(", ")}`;
  return "";
}
// src/lib/plattform/backend/demo/vorlagen.js
//
// E-Mail-/Nachrichtenvorlagen im Demo-Backend: Versionen (jede Änderung = neue Version, alte bleiben
// lesbar und wiederherstellbar), Vorschau mit echtem oder Beispielkontext, Versand an einen Kontakt
// bzw. als Portal-Nachricht im Thread eines Objekts. Platzhalter: src/lib/plattform/vorlagen.js.

import * as v from "../../validierung";
import { nichtGefunden, ungueltig } from "../../fehler";
import { VORLAGE_KANAELE, beispielKontext, rendern, vorlageFehler } from "../../vorlagen";
import { jetzt, neueId } from "./hilfen";
import { W, boAendern, boLesen, kontextFuer, nameVon, objektVon, portalPfad, rechtNoetig } from "./bo-kern";

const ARTEN = ["vorgang", "flaeche", "projekt", "interesse"];

function aktuelle(vl) {
  return vl.versionen.find((x) => x.version === vl.version) || vl.versionen[vl.versionen.length - 1];
}

function ausgabe(db, vl) {
  const a = aktuelle(vl);
  return {
    id: vl.id,
    name: vl.name,
    kanal: vl.kanal,
    aktiv: vl.aktiv !== false,
    version: vl.version,
    betreff: a.betreff,
    text: a.text,
    geaendertAm: a.am,
    geaendertVon: nameVon(db, a.vonId) || "System",
    versionen: [...vl.versionen].reverse().map((x) => ({ ...x, von: nameVon(db, x.vonId) || "System" })),
    verwendetIn: db.bo.regeln.filter((r) => r.aktionen.some((x) => x.vorlageId === vl.id)).map((r) => ({ id: r.id, name: r.name })),
  };
}

/** Vorlage auf ein Objekt anwenden → { betreff, text, unbekannt, leer } */
export function vorlageAnwenden(db, vl, art, o, { kontakt } = {}) {
  const a = aktuelle(vl);
  const ktx = kontextFuer(db, art, o, { kontakt });
  const b = rendern(a.betreff || "", ktx);
  const t = rendern(a.text || "", ktx);
  return { betreff: b.text, text: t.text, unbekannt: [...new Set([...b.unbekannt, ...t.unbekannt])], leer: [...new Set([...b.leer, ...t.leer])], kontext: ktx };
}

export const vorlageVon = (db, id) => db.bo.vorlagen.find((x) => x.id === id) || null;

export async function vorlagen(n) {
  rechtNoetig(n, "vorlagen", 1);
  const db = await boLesen();
  return db.bo.vorlagen.map((vl) => ausgabe(db, vl)).sort((a, b) => Number(b.aktiv) - Number(a.aktiv) || a.name.localeCompare(b.name, "de"));
}

export async function vorlageSpeichern(n, id, daten = {}) {
  rechtNoetig(n, "vorlagen", 2);
  const d = { name: v.text(daten.name, 120), kanal: v.auswahl(daten.kanal, VORLAGE_KANAELE, "email"), betreff: v.text(daten.betreff, 200), text: v.mehrzeilig(daten.text, 8000) };
  const f = vorlageFehler(d);
  if (f) throw ungueltig(f);
  return boAendern((db) => {
    let vl = id ? vorlageVon(db, id) : null;
    if (id && !vl) throw nichtGefunden("Vorlage nicht gefunden.");
    const kommentar = v.text(daten.kommentar, 200);
    if (!vl) {
      vl = { id: neueId("VL"), name: d.name, kanal: d.kanal, aktiv: true, version: 1, versionen: [{ version: 1, betreff: d.betreff, text: d.text, am: jetzt(), vonId: n.id, kommentar: kommentar || "Erste Fassung" }], erstelltAm: jetzt() };
      db.bo.vorlagen.push(vl);
      W.protokoll(db, n, "vorlage", "vorlage", vl.id, `Vorlage angelegt: ${d.name}`);
      return ausgabe(db, vl);
    }
    const a = aktuelle(vl);
    vl.name = d.name;
    vl.kanal = d.kanal;
    if (typeof daten.aktiv === "boolean") vl.aktiv = daten.aktiv;
    if (a.betreff !== d.betreff || a.text !== d.text) {
      const neu = Math.max(...vl.versionen.map((x) => x.version)) + 1;
      vl.versionen.push({ version: neu, betreff: d.betreff, text: d.text, am: jetzt(), vonId: n.id, kommentar });
      if (vl.versionen.length > 50) vl.versionen.splice(0, vl.versionen.length - 50);
      vl.version = neu;
      W.protokoll(db, n, "vorlage", "vorlage", vl.id, `Vorlage „${d.name}“: Version ${neu}${kommentar ? ` (${kommentar})` : ""}`);
    }
    return ausgabe(db, vl);
  });
}

export async function vorlageWiederherstellen(n, id, version) {
  rechtNoetig(n, "vorlagen", 2);
  return boAendern((db) => {
    const vl = vorlageVon(db, id);
    if (!vl) throw nichtGefunden("Vorlage nicht gefunden.");
    const alt = vl.versionen.find((x) => x.version === Number(version));
    if (!alt) throw nichtGefunden("Version nicht gefunden.");
    const neu = Math.max(...vl.versionen.map((x) => x.version)) + 1;
    vl.versionen.push({ version: neu, betreff: alt.betreff, text: alt.text, am: jetzt(), vonId: n.id, kommentar: `Wiederhergestellt aus Version ${alt.version}` });
    vl.version = neu;
    W.protokoll(db, n, "vorlage", "vorlage", vl.id, `Vorlage „${vl.name}“: Version ${alt.version} als ${neu} wiederhergestellt`);
    return ausgabe(db, vl);
  });
}

function zielObjekt(db, bezugArt, bezugId) {
  if (!bezugArt) return null;
  v.pflicht(ARTEN.includes(bezugArt), "Unbekannte Objektart.");
  const o = objektVon(db, bezugArt, v.kennung(bezugId));
  if (!o) throw nichtGefunden("Objekt für die Vorschau nicht gefunden.");
  return o;
}

/** Vorschau: mit Objekt/Kontakt echte Werte, sonst Beispielwerte. Ungespeicherter Text möglich. */
export async function vorlageVorschau(n, { vorlageId, betreff, text, bezugArt, bezugId, kontaktId } = {}) {
  rechtNoetig(n, "vorlagen", 1);
  const db = await boLesen();
  const vl = vorlageId ? vorlageVon(db, vorlageId) : null;
  if (vorlageId && !vl) throw nichtGefunden("Vorlage nicht gefunden.");
  const quelle = { betreff: betreff !== undefined ? v.text(betreff, 200) : vl ? aktuelle(vl).betreff : "", text: text !== undefined ? v.mehrzeilig(text, 8000) : vl ? aktuelle(vl).text : "" };
  const o = zielObjekt(db, bezugArt, bezugId);
  const kontakt = kontaktId ? db.bo.kontakte.find((k) => k.id === kontaktId) : null;
  if (kontaktId && !kontakt) throw nichtGefunden("Kontakt nicht gefunden.");
  const ktx = o || kontakt ? kontextFuer(db, bezugArt, o, { kontakt }) : beispielKontext();
  const b = rendern(quelle.betreff, ktx);
  const t = rendern(quelle.text, ktx);
  return { betreff: b.text, text: t.text, unbekannt: [...new Set([...b.unbekannt, ...t.unbekannt])], leer: [...new Set([...b.leer, ...t.leer])], beispiel: !(o || kontakt) };
}

/** Vorlage senden: E-Mail an Kontakt (Postausgang) oder Portal-Nachricht im Thread des Objekts */
export async function vorlageSenden(n, { vorlageId, kontaktId, bezugArt, bezugId } = {}) {
  rechtNoetig(n, "vorlagen", 1);
  rechtNoetig(n, "crm", 2);
  return boAendern((db) => {
    const vl = vorlageVon(db, v.kennung(vorlageId));
    if (!vl || vl.aktiv === false) throw nichtGefunden("Vorlage nicht gefunden oder inaktiv.");
    const o = zielObjekt(db, bezugArt, bezugId);
    const kontakt = kontaktId ? db.bo.kontakte.find((k) => k.id === kontaktId) : null;
    if (kontaktId && !kontakt) throw nichtGefunden("Kontakt nicht gefunden.");
    const r = vorlageAnwenden(db, vl, bezugArt, o, { kontakt });
    if (r.unbekannt.length) throw ungueltig(`Die Vorlage enthält unbekannte Platzhalter: ${r.unbekannt.join(", ")}`);
    if (vl.kanal === "nachricht") {
      v.pflicht(o, "Portal-Nachrichten brauchen ein Objekt (Vorgang, Fläche, Projekt, Interesse).");
      const m = W.nachricht(db, { bezugArt, bezugId: o.id, vonId: n.id, vonAdmin: true, text: r.text });
      W.protokoll(db, n, "vorlage_gesendet", bezugArt, o.id, `Nachricht aus Vorlage „${vl.name}“ (v${vl.version})`);
      return { ok: true, kanal: "nachricht", id: m.id };
    }
    const email = kontakt?.email || r.kontext.email;
    v.pflicht(email, "Für diesen Kontakt ist keine E-Mail-Adresse hinterlegt.");
    const e = W.postausgangAnlegen(db, { an: email, anName: [r.kontext.vorname, r.kontext.nachname].filter(Boolean).join(" "), nutzerId: kontakt?.nutzerId || null, art: "vorlage", betreff: r.betreff, text: r.text, link: portalPfad(bezugArt, o), linkText: "Zum Portal", hinweis: `Vorlage „${vl.name}“ (Version ${vl.version}), gesendet von ${nameVon(db, n.id)}.` });
    if (kontakt) {
      db.bo.aktivitaeten.push({ id: neueId("KA"), kontaktId: kontakt.id, organisationId: kontakt.organisationId || null, typ: "email", betreff: v.text(r.betreff, 160), text: v.mehrzeilig(r.text, 3000), am: jetzt(), bezugArt: o ? bezugArt : null, bezugId: o?.id || null, vonId: n.id, system: false, aufgabeId: null, wiedervorlageAm: null, erstelltAm: jetzt(), vorlageId: vl.id });
    }
    W.protokoll(db, n, "vorlage_gesendet", o ? bezugArt : "kontakt", o?.id || kontakt?.id || "", `E-Mail aus Vorlage „${vl.name}“ (v${vl.version}) an ${email}`);
    return { ok: true, kanal: "email", id: e.id };
  });
}
// src/lib/plattform/server/pdf.js
//
// Kleiner PDF-Erzeuger ohne Fremdpakete: mehrere Seiten (A4), Standardschriften Helvetica und
// Helvetica-Bold (WinAnsi/CP1252, also mit Umlauten, ß, €, „“ – –), Flächen, Linien, Farben,
// Textbreiten nach den Adobe-Metriken (für sauberen Zeilenumbruch). Koordinaten: Punkte, Ursprung
// OBEN links (wird intern umgerechnet), y beim Text = Grundlinie.
//
// Nur serverseitig (Buffer). Genutzt für Exposé-PDFs und die Demo-Dokumente.

export const A4 = { breite: 595.28, hoehe: 841.89 };

// Zeichenbreiten (1/1000 em) für die Zeichen 32–126
const W_REG = [
  278, 278, 355, 556, 556, 889, 667, 191, 333, 333, 389, 584, 278, 333, 278, 278, 556, 556, 556, 556, 556, 556, 556, 556, 556, 556, 278, 278, 584, 584, 584, 556,
  1015, 667, 667, 722, 722, 667, 611, 778, 722, 278, 500, 667, 556, 833, 722, 778, 667, 778, 722, 667, 611, 722, 667, 944, 667, 667, 611, 278, 278, 278, 469, 556,
  333, 556, 556, 500, 556, 556, 278, 556, 556, 222, 222, 500, 222, 833, 556, 556, 556, 556, 333, 500, 278, 556, 500, 722, 500, 500, 500, 334, 260, 334, 584,
];
const W_BOLD = [
  278, 333, 474, 556, 556, 889, 722, 238, 333, 333, 389, 584, 278, 333, 278, 278, 556, 556, 556, 556, 556, 556, 556, 556, 556, 556, 333, 333, 584, 584, 584, 611,
  975, 722, 722, 722, 722, 667, 611, 778, 722, 278, 556, 722, 611, 833, 722, 778, 667, 778, 722, 667, 611, 722, 667, 944, 667, 667, 611, 333, 278, 333, 584, 556,
  333, 556, 611, 556, 611, 556, 333, 611, 611, 278, 278, 556, 278, 889, 611, 611, 611, 611, 389, 556, 333, 611, 556, 778, 556, 556, 500, 389, 280, 389, 584,
];
// Sonderzeichen: [Breite normal, Breite fett, CP1252-Code]
const SONDER = {
  "€": [556, 556, 0x80], "‚": [222, 278, 0x82], "„": [333, 500, 0x84], "…": [1000, 1000, 0x85], "‰": [1000, 1000, 0x89],
  "‘": [222, 278, 0x91], "’": [222, 278, 0x92], "“": [333, 500, 0x93], "”": [333, 500, 0x94], "•": [350, 350, 0x95],
  "–": [556, 556, 0x96], "—": [1000, 1000, 0x97], "™": [1000, 1000, 0x99], "ß": [611, 611, 0xdf], "·": [278, 278, 0xb7],
  "°": [400, 400, 0xb0], "²": [333, 333, 0xb2], "³": [333, 333, 0xb3], "×": [584, 584, 0xd7], "«": [556, 556, 0xab],
  "»": [556, 556, 0xbb], "§": [556, 556, 0xa7], "©": [737, 737, 0xa9], "®": [737, 737, 0xae], "±": [584, 584, 0xb1],
};
const ERSATZ = [
  [/[    ]/g, " "], [/≥/g, ">="], [/≤/g, "<="], [/→/g, "->"], [/≈/g, "ca. "], [/[‐‑]/g, "-"],
  [/[​-‍﻿]/g, ""], [/\t/g, " "],
];

/** Text für die Ausgabe vereinheitlichen (Zeichen außerhalb von CP1252 ersetzen) */
export function normalisieren(s) {
  let t = String(s ?? "");
  for (const [re, x] of ERSATZ) t = t.replace(re, x);
  return t;
}

function zeichen(c) {
  const code = c.charCodeAt(0);
  if (code >= 32 && code <= 126) return { code, basis: c };
  if (SONDER[c]) return { code: SONDER[c][2], sonder: SONDER[c] };
  if (code >= 0xa0 && code <= 0xff) {
    const basis = c.normalize("NFD")[0];
    return { code, basis: basis.charCodeAt(0) >= 32 && basis.charCodeAt(0) <= 126 ? basis : "o" };
  }
  return { code: 63, basis: "?" };
}

/** Breite eines Texts in Punkten */
export function textBreite(text, groesse = 10, fett = false) {
  let summe = 0;
  for (const c of normalisieren(text)) {
    const z = zeichen(c);
    if (z.sonder) summe += z.sonder[fett ? 1 : 0];
    else summe += (fett ? W_BOLD : W_REG)[z.basis.charCodeAt(0) - 32] ?? 556;
  }
  return (summe * groesse) / 1000;
}

/** Zeilenumbruch nach Breite (Wörter; überlange Wörter werden hart getrennt) */
export function umbrechen(text, maxBreite, groesse = 10, fett = false) {
  const zeilen = [];
  for (const absatz of normalisieren(text).split(/\n/)) {
    const woerter = absatz.split(/ +/).filter((w, i, a) => w || a.length === 1);
    let zeile = "";
    for (let wort of woerter) {
      while (textBreite(wort, groesse, fett) > maxBreite && wort.length > 1) {
        // überlanges Wort (z. B. URL) zerlegen
        let n = wort.length - 1;
        while (n > 1 && textBreite(wort.slice(0, n), groesse, fett) > maxBreite) n--;
        if (zeile) {
          zeilen.push(zeile);
          zeile = "";
        }
        zeilen.push(wort.slice(0, n));

        zeilen.push(wort.slice(0, n));
        wort = wort.slice(n);
      }
      const versuch = zeile ? `${zeile} ${wort}` : wort;
      if (textBreite(versuch, groesse, fett) <= maxBreite) zeile = versuch;
      else {
        if (zeile) zeilen.push(zeile);
        zeile = wort;
      }
    }
    zeilen.push(zeile);
  }
  return zeilen;
}

/** PDF-Stringliteral (Bytes in CP1252, maskiert) */
function literal(text) {
  let s = "";
  for (const c of normalisieren(text)) {
    const { code } = zeichen(c);
    if (code === 0x28 || code === 0x29 || code === 0x5c) s += "\\" + String.fromCharCode(code);
    else if (code < 32) s += " ";
    else s += String.fromCharCode(code);
  }
  return `(${s})`;
}

function farbe(hex, fuellen = true) {
  const h = String(hex || "#000000").replace("#", "");
  const [r, g, b] = [0, 2, 4].map((i) => (parseInt(h.slice(i, i + 2), 16) / 255).toFixed(3));
  return `${r} ${g} ${b} ${fuellen ? "rg" : "RG"}`;
}

const zahl = (n) => (Math.round(n * 100) / 100).toString();

class Seite {
  constructor(dok) {
    this.dok = dok;
    this.ops = [];
  }

  y(oben) {
    return zahl(this.dok.hoehe - oben);
  }

  rechteck(x, y, b, h, fuellung, { rand, randBreite = 0.75 } = {}) {
    const pfad = `${zahl(x)} ${this.y(y + h)} ${zahl(b)} ${zahl(h)} re`;
    if (fuellung && rand) this.ops.push(`${farbe(fuellung)} ${farbe(rand, false)} ${zahl(randBreite)} w ${pfad} B`);
    else if (fuellung) this.ops.push(`${farbe(fuellung)} ${pfad} f`);
    else if (rand) this.ops.push(`${farbe(rand, false)} ${zahl(randBreite)} w ${pfad} S`);
    return this;
  }

  linie(x1, y1, x2, y2, { farbe: f = "#dfe3ea", breite = 0.75 } = {}) {
    this.ops.push(`${farbe(f, false)} ${zahl(breite)} w ${zahl(x1)} ${this.y(y1)} m ${zahl(x2)} ${this.y(y2)} l S`);
    return this;
  }

  /** Text an Grundlinie y; `ausrichtung` links | rechts | mitte (bezogen auf x) */
  text(x, y, text, { groesse = 10, fett = false, farbe: f = "#151a24", ausrichtung = "links", zeichenabstand = 0 } = {}) {
    const t = normalisieren(text);
    if (!t) return this;
    const breite = textBreite(t, groesse, fett) + zeichenabstand * Math.max(0, t.length - 1);
    const xs = ausrichtung === "rechts" ? x - breite : ausrichtung === "mitte" ? x - breite / 2 : x;
    const tc = `${zahl(zeichenabstand)} Tc `; // Zeichenabstand gilt über BT/ET hinaus – immer explizit setzen
    this.ops.push(`BT ${farbe(f)} /${fett ? "F2" : "F1"} ${zahl(groesse)} Tf ${tc}${zahl(xs)} ${this.y(y)} Td ${literal(t)} Tj ET`);
    return this;
  }

  /** Mehrzeiliger Text ab Grundlinie y, liefert die y-Position nach der letzten Zeile */
  absatz(x, y, text, { breite, groesse = 10, fett = false, farbe: f, zeilenhoehe } = {}) {
    const zh = zeilenhoehe || groesse * 1.45;
    let yy = y;
    for (const z of umbrechen(text, breite, groesse, fett)) {
      this.text(x, yy, z, { groesse, fett, farbe: f });
      yy += zh;
    }
    return yy - zh;
  }

  /**
   * Bild (aus server/png.js → pngLesen) in das Rechteck x/y (oben links), Breite b, Höhe h zeichnen.
   * Elektronische Unterschrift: gezeichnete Signatur auf der Prüfseite.
   */
  bild(x, y, b, h, bild) {
    if (!bild?.daten) return this;
    const name = this.dok.bildName(bild);
    this.ops.push(`q ${zahl(b)} 0 0 ${zahl(h)} ${zahl(x)} ${this.y(y + h)} cm /${name} Do Q`);
    return this;
  }

  inhalt() {
    return this.ops.join("\n");
  }
}

export class PdfDokument {
  constructor({ titel = "Dokument", autor = "ÖkoInvest GmbH", thema = "" } = {}) {
