export function stichproben(geometrie) {
  const pkt = [];
  for (const poly of ringe(geometrie)) {
    const r = poly[0] || [];
    for (let i = 1; i < r.length; i++) pkt.push(r[i - 1], [(r[i - 1][0] + r[i][0]) / 2, (r[i - 1][1] + r[i][1]) / 2]);
