    const u = nutzer && nutzer.email === k.email && nutzer.emailBestaetigt ? nutzerById(db, nutzer.id) : null;
    const vg = {
      id: neueId("V"),
      typ: t,
      status: PROZESSE.vorgang.start,
      statusVerlauf: [verlaufEintrag(PROZESSE.vorgang.start, u, "eigentuemer", "")],
      nutzerId: u?.id || null,
      email: k.email,
      kontakt: k,
      daten: d,
      herkunft: h,
      ip: ip || "",
      einwilligung: { am: jetzt(), ip: ip || "", text: v.text(einwilligungText, 400) },
      zustaendigId: null,
      flaecheId: null,
      erstelltAm: jetzt(),
      geaendertAm: jetzt(),
    };
    if (t === "flaeche" || t === "agri") {
      const haWert = v.zahl(d.ha ?? d.hektar ?? d.flaeche ?? d.flaecheHa, { min: 0, max: 100000, stellen: 2 });
      const f = {
        id: neueId("F"),
        nutzerId: u?.id || null,
        vorgangId: vg.id,
        bezeichnung: v.text(d.bezeichnung, 120) || `Fläche ${[k.plz, k.ort].filter(Boolean).join(" ") || "aus Anfrage"}`,
        land: k.land || "DE",
        bundesland: v.auswahl(d.bundesland, BUNDESLAENDER[k.land || "DE"] || [], ""),
        plz: k.plz,
        ort: k.ort,
        gemarkung: "",
        flurstuecke: [],
        ha: haWert,
        nutzung: d.art === "dach" ? "dach" : v.auswahl(d.nutzung, FLAECHE_NUTZUNG, "acker"), // /dachflaeche-verpachten sendet daten.art = "dach"
        agri: t === "agri",
        eigentum: "eigentum",
        fach: fachAusAnfrage(t, d), // z. B. Dachart/Dachfläche aus /dachflaeche-verpachten
        hinweise: v.mehrzeilig(d.nachricht, 2000),
        status: "entwurf",
        statusVerlauf: [verlaufEintrag("entwurf", u, "system", "Aus Anfrage angelegt")],
        pachtangebot: null,
        ablehnGrund: "",
        zustaendigId: null,
        erstelltAm: jetzt(),
        geaendertAm: jetzt(),
      };
      db.flaechen.push(f);
      vg.flaecheId = f.id;
    }
    db.vorgaenge.push(vg);
    protokoll(db, u, "anfrage", "vorgang", vg.id, `Anfrage ${VORGANG_TYPEN[t]} von ${k.email}`, ip);
    backofficeEreignis(db, { typ: "vorgang_neu", art: "vorgang", objekt: vg }); // CRM-Lead + Automationen
    for (const a of aktiveAdmins(db)) {
      benachrichtigen(db, a, { art: "anfrage", titel: `Neue Anfrage: ${VORGANG_TYPEN[t]}`, text: `${k.vorname} ${k.nachname}${k.firma ? ` · ${k.firma}` : ""} · ${vg.id}`, link: `/portal/admin/vorgaenge/${vg.id}`, objektArt: "vorgang", objektId: vg.id });
    }
    return { id: vg.id, vorgang: { id: vg.id, typ: vg.typ, status: vg.status, flaecheId: vg.flaecheId } };
  });
}

// ================================================================ Vorgänge

function vorgangListenEintrag(db, vg, admin) {
  const z = nutzerById(db, vg.zustaendigId);
  const letzte = vg.statusVerlauf[vg.statusVerlauf.length - 1];
  return {
    id: vg.id,
    typ: vg.typ,
    status: vg.status,
    erstelltAm: vg.erstelltAm,
    geaendertAm: vg.geaendertAm,
    kontakt: { vorname: vg.kontakt.vorname, nachname: vg.kontakt.nachname, firma: vg.kontakt.firma, email: vg.email },
    nutzerId: admin ? vg.nutzerId : undefined,
    zustaendig: z ? kurz(z) : null,
    flaecheId: vg.flaecheId,
    letzterKommentar: letzte?.kommentar || "",
  };
}

export async function vorgaenge(n, { alle = false, status, typ, q } = {}) {
  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
  if (alle) adminNoetig(n);
  const db = await lesen();
  let liste = alle ? db.vorgaenge : db.vorgaenge.filter((x) => x.nutzerId === n.id);
  if (status) liste = liste.filter((x) => x.status === status);
  if (typ) liste = liste.filter((x) => x.typ === typ);
  if (q) {
    const s = String(q).toLowerCase();
    liste = liste.filter((x) => [x.id, x.email, x.kontakt.vorname, x.kontakt.nachname, x.kontakt.firma].join(" ").toLowerCase().includes(s));
  }
  return liste.sort(nachDatum()).map((x) => vorgangListenEintrag(db, x, alle));
}

// src/lib/plattform/server/rateLimit.js
//
// Einfaches Rate-Limit im Arbeitsspeicher (gleitendes Fenster je Schlüssel).
// Reicht für einen einzelnen Node-Prozess; bei mehreren Instanzen zusätzlich
// am Reverse-Proxy (nginx limit_req) begrenzen – siehe docs/PLATTFORM.md.

import { PlattformFehler } from "../fehler";

const speicher = (globalThis.__oiRateLimit ||= new Map());

/** Wirft 429, wenn `schluessel` mehr als `max` Treffer im Fenster hat */
export function rateLimit(schluessel, max, fensterMs) {
  const jetzt = Date.now();
  const liste = (speicher.get(schluessel) || []).filter((t) => jetzt - t < fensterMs);
  if (liste.length >= max) {
    speicher.set(schluessel, liste);
    throw new PlattformFehler(429, "Zu viele Versuche in kurzer Zeit – bitte warten Sie einige Minuten.");
  }
  liste.push(jetzt);
  speicher.set(schluessel, liste);

  // gelegentlich aufräumen
  if (speicher.size > 5000) {
    for (const [k, v] of speicher) if (!v.length || jetzt - v[v.length - 1] > 3600e3) speicher.delete(k);
  }
}

/** Grenzen je Aktion: [max, Fenster in ms] */
export const GRENZEN = {
  login: [10, 15 * 60e3],
  loginEmail: [8, 15 * 60e3],
  registrieren: [5, 60 * 60e3],
  anfrage: [10, 60 * 60e3],
  passwort: [5, 60 * 60e3],
  upload: [60, 60 * 60e3],
  nachricht: [120, 60 * 60e3],
  // Login, Sicherheit & Teams
  magicLink: [5, 60 * 60e3],
  zweiFaktor: [10, 15 * 60e3],
  einladung: [30, 60 * 60e3],
  export: [10, 60 * 60e3],
};

/**
 * In der Entwicklung sind die Grenzen 10-fach gelockert (wiederholte Testläufe),
 * über PLATTFORM_RATE_FAKTOR einstellbar. In Produktion gilt immer Faktor 1.
 */
export function grenze(name) {
  const [max, fenster] = GRENZEN[name];
  const faktor = process.env.NODE_ENV !== "production" ? Number(process.env.PLATTFORM_RATE_FAKTOR) || 10 : 1;
  return [Math.max(1, Math.round(max * faktor)), fenster];
}
