export const KEIN_INTERESSE = {
  DE: "Haben Sie kein Interesse, müssen Sie nichts tun. Möchten Sie keine weiteren Schreiben von uns erhalten, genügt ein kurzer Widerspruch – dann schreiben wir Sie nie wieder an.",
