import GoogleAnalytics from "@/components/Statistik/GoogleAnalytics";
import "./globals.css";
import { Inter, Manrope } from "next/font/google";
import LayoutWrapper from "@/components/Reusable/LayoutWrapper";
import { GESELLSCHAFT, SITE } from "@/data/site";

// Zwei Schriften wie auf oekovolt.de: Inter für Fließtext, Manrope für
// Überschriften. next/font hostet beide selbst (keine Verbindung zu Google).
const inter = Inter({
  subsets: ["latin", "latin-ext"],
  display: "swap",
  variable: "--font-inter",
  fallback: ["system-ui", "Segoe UI", "Arial", "sans-serif"],
});

const manrope = Manrope({
  subsets: ["latin", "latin-ext"],
  weight: ["500", "600", "700", "800"],
  display: "swap",
  variable: "--font-manrope",
  fallback: ["system-ui", "Segoe UI", "Arial", "sans-serif"],
});

const BASE_URL = SITE.url;

const siteSchema = {
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "Organization",
      "@id": `${BASE_URL}/#organization`,
      name: "ÖkoInvest",
      legalName: GESELLSCHAFT.name,
      alternateName: ["Oekoinvest", "ÖkoInvest GmbH", "ÖKOINVEST"],
      url: BASE_URL,
      description: SITE.kurz,
      slogan: SITE.claim,
      foundingDate: "2020-09-10",
      address: {
        "@type": "PostalAddress",
        streetAddress: GESELLSCHAFT.sitz,
        addressLocality: GESELLSCHAFT.ort,
        postalCode: GESELLSCHAFT.plz,
        addressCountry: "AT",
      },
      identifier: { "@type": "PropertyValue", propertyID: "Firmenbuchnummer", value: GESELLSCHAFT.register },
      parentOrganization: { "@type": "Organization", name: "ÖKOVOLT Gruppe", url: SITE.gruppeUrl },
      areaServed: [
        { "@type": "Country", name: "Deutschland" },
        { "@type": "Country", name: "Österreich" },
        { "@type": "Country", name: "Schweiz" },
      ],
      knowsAbout: [
        "Freiflächen-Photovoltaik",
        "Agri-Photovoltaik",
        "Solarcarports",
        "Projektentwicklung Solarpark",
        "Flächenpacht Photovoltaik",
        "Projektrechte Photovoltaik",
        "Power Purchase Agreement",
        "Virtuelles Kraftwerk",
        "Energiegemeinschaften",
        "Energiegenossenschaft",
        "Batteriegroßspeicher",
      ],
    },
    {
      "@type": "WebSite",
      "@id": `${BASE_URL}/#website`,
      url: BASE_URL,
      name: "ÖkoInvest",
      inLanguage: "de",
      publisher: { "@id": `${BASE_URL}/#organization` },
    },
  ],
};

export const viewport = {
  themeColor: "#669933",
  width: "device-width",
import { cn } from "./cn";

const TOENE = {
  white: "bg-white text-ink-900",
  sand: "bg-sand-50 text-ink-900",
  ink: "bg-ink-50 text-ink-900",
  green: "bg-ov-50 text-ink-900",
  navy: "bg-navy-950 text-white",
};

const ABSTAENDE = {
  none: "",
  sm: "py-12 md:py-16",
  md: "py-16 md:py-24",
  lg: "py-20 md:py-32",
};

/**
 * Seitenabschnitt mit einheitlichem Rhythmus.
 * tone: white | sand | ink | green | navy
 * space: none | sm | md | lg
 */
export default function Section({
  tone = "white",
  space = "md",
  id,
  className,
  containerClassName,
  bare = false,
  as: Tag = "section",
  children,
  ...rest
}) {
  return (
    <Tag
      id={id}
      className={cn("relative", TOENE[tone], ABSTAENDE[space], className)}
      {...rest}
    >
      {bare ? children : <div className={cn("ov-container relative", containerClassName)}>{children}</div>}

"use client";

import { useEffect, useState } from "react";
import { usePathname } from "next/navigation";

/**
 * Google Analytics 4 – wird erst nach Einwilligung („Statistik“ im Cookie-Banner) geladen.
 *
 * Umgebungsvariable: NEXT_PUBLIC_GA_ID (Mess-ID, z. B. G-XXXXXXXXXX)
 *
 * - Vor der Einwilligung: kein Skript, keine Verbindung zu Google, keine Cookies.
 * - Google Consent Mode v2: Standard „denied“, nach Einwilligung nur analytics_storage „granted“
 *   (keine Werbe-/Personalisierungsfreigaben).
 * - Widerruf: Messung wird sofort gestoppt und die _ga-Cookies werden gelöscht.
 * - Seiten mit Einmal-Tokens (/scan, /fortsetzen) und die Info-Bildschirme (/tv) werden nie gemessen;
 *   von URL-Parametern werden nur utm_* übertragen.
 */
// Eigene GA4-Property für ÖkoInvest – ohne Mess-ID wird nichts geladen (nie die ID der DE-Seite)
const GA_ID = process.env.NEXT_PUBLIC_GA_ID || null;
const AUSGENOMMEN = /^\/(scan|fortsetzen|tv)(\/|$)/;

export function statistikErlaubt() {
  if (typeof document === "undefined") return false;
  try {
    const roh = document.cookie.split("; ").find((c) => c.startsWith("cookieConsent="));
    if (!roh) return false;
    return JSON.parse(decodeURIComponent(roh.slice("cookieConsent=".length))).googleAnalytics === true;
  } catch {
    return false;
  }
}

function gtagVorbereiten() {
  window.dataLayer = window.dataLayer || [];
  if (!window.gtag) {
    window.gtag = function () {
      window.dataLayer.push(arguments);
    };
    window.gtag("consent", "default", {
      analytics_storage: "denied",
      ad_storage: "denied",
      ad_user_data: "denied",
      ad_personalization: "denied",
    });
  }
}

function laden() {
  window[`ga-disable-${GA_ID}`] = false;
  gtagVorbereiten();
  window.gtag("consent", "update", { analytics_storage: "granted" });
  if (window.ovGaGeladen) return;
  window.ovGaGeladen = true;
  window.gtag("js", new Date());
  // Seitenaufrufe senden wir selbst (bereinigte URL, Ausnahmen) – daher send_page_view: false
  window.gtag("config", GA_ID, { send_page_view: false, allow_google_signals: false, allow_ad_personalization_signals: false });
  const s = document.createElement("script");
