  p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 300)));
  const r = await p.goto("http://localhost:3100/portal/admin/akquise/karte", { waitUntil: "load", timeout: 180000 });
