  await p.waitForTimeout(3000);
  const ueber = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
  await p.screenshot({ path: ziel("karte") });
  console.log(r.status(), "karte", "Überlauf", ueber);
  // Steckbrief öffnen: Liste → erster Eintrag
  if (+breite < 1024) await p.getByRole("button", { name: "Panel" }).click();
  await p.getByRole("tab", { name: /Liste/ }).click();
  await p.locator("aside[aria-label='Filter und Flächenliste'] li button").first().waitFor({ timeout: 90000 });
  await p.locator("aside[aria-label='Filter und Flächenliste'] li button").first().click();
  await p.locator("aside[aria-label='Steckbrief']").waitFor({ timeout: 90000 });
  await p.waitForTimeout(2500);
  await p.screenshot({ path: ziel("steckbrief") });
  const ueber2 = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
  console.log("steckbrief", "Überlauf", ueber2, fehler.length ? "\n" + fehler.join("\n") : "");
} finally {
  await b.close();
}

