// Aufruf: node ak2_shot.mjs – Akquise A1b: Testkampagne anlegen, Karte DE, Kampagne, Gemeinden, Angebotsseite (390/1440).
// Ein Browser, immer schließen; Testkampagne wird am Ende gelöscht.
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const B = "http://localhost:3100";
const ziel = (n) => fileURLToPath(new URL(`./shots/ak2_${n}.png`, import.meta.url));
const b = await chromium.launch();
let kid = null;
let api = null;
try {
  const ctx = await b.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
  api = ctx.request;
  const o = { headers: { Origin: B }, timeout: 180000 };
  console.log("login", (await api.post(`${B}/api/auth/login`, { ...o, data: { email: "admin@example.com", passwort: "Demo-2026!" } })).status());
  const k = (await (await api.get(`${B}/api/admin/geodaten/kandidaten?land=DE&ampel=gruen&limit=50`, o)).json()).kandidaten;
  const r = await (await api.post(`${B}/api/admin/geodaten/kampagnen`, { ...o, data: { name: "Unterallgäu A 96 – Herbst 2026 (Test)", kandidatIds: k.slice(0, 4).map((x) => x.id), test: true } })).json();
  kid = r.kampagne.id;
  await api.post(`${B}/api/admin/geodaten/kampagnen/${kid}/starten`, { ...o, data: {} });
  const d = await (await api.get(`${B}/api/admin/geodaten/kampagnen/${kid}`, o)).json();
  await api.post(`${B}/api/admin/geodaten/kampagnen/ziele/${d.ziele[0].id}/grundbuch`, { ...o, data: { empfaenger: [{ anrede: "Frau", vorname: "Erika", nachname: "Musterfrau", strasse: "Mühlweg 7", plz: "86842", ort: "Türkheim" }], kostenIst: 20 } });
  await api.post(`${B}/api/admin/geodaten/kampagnen/ziele/${d.ziele[1].id}/grundbuch`, { ...o, data: { empfaenger: [{ anrede: "Herr", vorname: "Max", nachname: "Beispiel", strasse: "Am Anger 1", plz: "86807", ort: "Buchloe" }] } });
  await api.post(`${B}/api/admin/geodaten/kampagnen/${kid}/versand`, { ...o, data: { stufe: 1 } });
  const d2 = await (await api.get(`${B}/api/admin/geodaten/kampagnen/${kid}`, o)).json();
  const code = d2.ziele[0].empfaenger[0].code;

  const p = await ctx.newPage();
  const fehler = [];
  p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
  p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 200)));
  // 1. Karte Deutschland + Steckbrief
  await p.goto(`${B}/portal/admin/akquise/karte`, { waitUntil: "load", timeout: 180000 });
  await p.getByRole("button", { name: /Unterallgäu/ }).click({ timeout: 120000 });
  await p.waitForTimeout(4000);
  await p.getByRole("tab", { name: /Liste/ }).click();
  await p.locator("aside[aria-label='Filter und Flächenliste'] li button").first().click({ timeout: 90000 });
  await p.locator("aside[aria-label='Steckbrief']").waitFor({ timeout: 90000 });
  await p.waitForTimeout(3500);
  await p.screenshot({ path: ziel("karte_de_1440") });
  console.log("karte", fehler.splice(0).join(" | "));
  // 2. Kampagne (erstes Ziel aufgeklappt)
  await p.goto(`${B}/portal/admin/akquise/kampagnen/${kid}`, { waitUntil: "load", timeout: 180000 });
  await p.locator("ul li button[aria-expanded]").first().click();
  await p.waitForTimeout(800);
  await p.screenshot({ path: ziel("kampagne_1440"), fullPage: true });
  console.log("kampagne", await p.evaluate(() => document.documentElement.scrollWidth - innerWidth), fehler.splice(0).join(" | "));
  // 3. Gemeinde-Screening (erste Gemeinde aufgeklappt)
  await p.goto(`${B}/portal/admin/akquise/gemeinden`, { waitUntil: "load", timeout: 180000 });
  await p.locator("li > button[aria-expanded]").first().click();
  await p.waitForTimeout(800);
  await p.screenshot({ path: ziel("gemeinden_1440") });
  console.log("gemeinden", fehler.splice(0).join(" | "));
  // 4. Mobil: Kampagne 390 (Überlauf)
  await p.setViewportSize({ width: 390, height: 844 });
  await p.goto(`${B}/portal/admin/akquise/kampagnen/${kid}`, { waitUntil: "load", timeout: 180000 });
  await p.waitForTimeout(800);
  console.log("kampagne 390 Überlauf", await p.evaluate(() => document.documentElement.scrollWidth - innerWidth));
  await p.goto(`${B}/portal/admin/akquise/gemeinden`, { waitUntil: "load", timeout: 180000 });
  console.log("gemeinden 390 Überlauf", await p.evaluate(() => document.documentElement.scrollWidth - innerWidth), fehler.splice(0).join(" | "));
  // 5. Angebotsseite ohne Anmeldung (390 ganze Seite, 1440 sichtbarer Bereich)
  const gast = await b.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  const g = await gast.newPage();
  g.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
  g.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 200)));
  const res = await g.goto(`${B}/angebot/${code}`, { waitUntil: "load", timeout: 180000 });
  try { await g.getByRole("button", { name: "Nur notwendige" }).click({ timeout: 2500 }); } catch {}
  await g.waitForTimeout(1500);
  console.log("angebot", res.status(), "Überlauf", await g.evaluate(() => document.documentElement.scrollWidth - innerWidth));
  await g.screenshot({ path: ziel("angebot_390"), fullPage: true });
  await g.setViewportSize({ width: 1440, height: 900 });
  await g.waitForTimeout(800);
  await g.screenshot({ path: ziel("angebot_1440") });
  console.log("angebot", fehler.join(" | "));
  await gast.close();
} finally {
  if (kid && api) console.log("aufräumen", (await api.delete(`${B}/api/admin/geodaten/kampagnen/${kid}`, { headers: { Origin: B, "Content-Type": "application/json" }, data: {}, timeout: 180000 })).status());
  await b.close();
}

